cat << 'EOF' > Cargo.toml
[workspace]
resolver = "3"
members = [
    "primitives",
    "work",
    "scivm",
    "scheduler",
    "ledger",
    "poc",
    "wire",
    "chain",
    "node",
]

# Consensus code: no `unsafe`, and every public item documented.
[workspace.lints.rust]
unsafe_code = "forbid"
missing_docs = "warn"

[workspace.dependencies]
primitives = { path = "primitives" }
work = { path = "work" }
scivm = { path = "scivm" }
scheduler = { path = "scheduler" }
ledger = { path = "ledger" }
wire = { path = "wire" }
chain = { path = "chain" }

# FIPS 202. Since sha3 0.12, RustCrypto ships SHAKE in the sibling `shake` crate
# (same repository, same `keccak` backend).
sha3 = { version = "0.12.0", default-features = false }
shake = { version = "0.1.0", default-features = false }
# FIPS 204 ML-DSA-87 (RustCrypto). Shares `shake` and `keccak` with the hashing above.
ml-dsa = { version = "0.1.1", default-features = false, features = ["alloc", "getrandom"] }

serde = { version = "1.0.228", features = ["derive"] }
# 3.0.0 is a compile_error! tombstone (RUSTSEC-2025-0141); 1.3.3 is declared complete.
bincode = "=1.3.3"
serde_json = "1"
tokio = { version = "1.53", features = [
    "rt-multi-thread",
    "macros",
    "net",
    "sync",
    "time",
    "signal",
    "fs",
] }
tokio-util = { version = "0.7.20", features = ["codec"] }
futures = "0.3.34"
bytes = "1"
axum = "0.8.9"
clap = { version = "4.6", features = ["derive"] }
tracing = "0.1.44"
tracing-subscriber = { version = "0.3.23", features = ["env-filter"] }

# One 512^3 tile at opt-level 0 is roughly 30x slower; tests mine and verify real tiles.
[profile.dev.package.work]
opt-level = 3
[profile.dev.package.primitives]
opt-level = 3
[profile.dev.package.scivm]
opt-level = 3
# Each tile check hashes about 1.5 MB with SHA3-512, so the Keccak crates need it too.
[profile.dev.package.keccak]
opt-level = 3
[profile.dev.package.sha3]
opt-level = 3
[profile.dev.package.shake]
opt-level = 3
# ML-DSA-87 signs and verifies every block, share and job.
[profile.dev.package.ml-dsa]
opt-level = 3
[profile.dev.package.module-lattice]
opt-level = 3
EOF

cat << 'EOF' > README.md
# Plauthium workspace: core + Public Testnet v1

Rust workspace for the Plauthium post-quantum layer-1. The six core crates are a frozen,
tested mathematical core that follows the *Plauthium Technical Specification*. Three
testnet crates wrap it into a multi-node P2P network, as specified in
[`../testnet_blueprint.md`](../testnet_blueprint.md). `unsafe` is forbidden everywhere,
and every public item is documented.

```sh
cargo test --workspace --release   # 88 tests, including the 3-node integration test (~2-3 min)
cargo run -p poc                   # core: mock block transition + ASCII summary
scripts/testnet.sh                 # join the public testnet, or run a local 3-node dev net
```

Run the tests in release mode. Every block involves at least one real 512×512 tile product.
The workspace needs Rust 1.89 or newer.

## Crates

| Crate        | Spec      | Contents |
|--------------|-----------|----------|
| `primitives` | §1.3–1.4, Table 3, §7.10 | `Atoms` (1 PLAU = 10^8 atoms), supply `M = 1.5·10^15`, `Mersenne61` field (`p = 2^61 − 1`), `DomainSeparatedHash` (SHA3-512) + `Shake256Xof` (SHAKE256), `BlockResourceVector` (5 components), PQ object sizes |
| `work`       | §3.1–3.2, §5.1–5.2 | 512×512 INT8 `WorkUnit` over `[-127, 127]`, INT32 `AccumulationTarget` with `\|z\| ≤ 8,258,048 < 2^23`, exact tile product, 16-field Fresh Work context, seed expansion by byte rejection, `verify_freivalds_rounds` (`r_F = 6`) |
| `scivm`      | §3.6      | `OzakiIIProfile` (pairwise-coprime moduli ≤ 255, `Q > 2·B_rec`), `split_residues`, centered CRT, exact residue dot product, zero consensus weight |
| `scheduler`  | §6.1–6.5  | `ShareID`, sequential D'Hondt (`w_s/(a_s+1)` by exact cross-multiplication, ties to least ShareID), owner capacity, persistent cohort counters |
| `ledger`     | §7.1–7.8  | 8 disjoint `StateCategory` balances, atomic zero-sum deltas, `FounderVesting` (1,460 daily tranches × 720 blocks), `FeeLot` with ceiling budgets, floor payouts and segregated dust |
| `poc`        | —         | Binary that runs Genesis → Fresh Work → D'Hondt → Base Fee lock/maturation/payout |
| `wire`       | blueprint §3–§5 | The six P2P messages (incl. `GossipShare`; the `Handshake` carries the genesis id and a node nonce), block/job/share types, `Digest`/`Target`, fixed-width ML-DSA-87 `PublicKey`/`Signature`, the bincode 1.3.3 codec (fixed-width little-endian, trailing bytes rejected), protocol constants |
| `chain`      | blueprint §6–§7 | Genesis validation, Stage A (signatures, then VerifyFW by recomputing the tile) and Stage B (context checks), windowed retarget, `apply_body` (the state transition on `ledger::Ledger`), D'Hondt leases, templates, `BlockTree` with heaviest-seal-weight fork choice, ML-DSA-87 owner keys (`chain::keys`) |
| `node`       | blueprint §8–§10 | `plauthium-node`: ChainState / Mempool actors, multi-threaded ConsensusEngine, length-delimited TCP PeerManager with sync, append-only `blocks.log`, persistent miner key, share pool with `GossipShare` relay, Stage A limits per source, host-name bootnodes, axum JSON RPC and the embedded explorer |

## Running a node

`bash Plauthium_Testnet.sh` (the whole workspace in one script, generated by
`scripts/make_bundle.sh`) prints the testnet disclaimer, asks which of three to run,
writes the workspace, builds `plauthium-node` and starts it. `scripts/testnet.sh` does the
same from a checkout, and `--miner`, `--verifier` and `--local` choose without asking:

1. **`--miner`**: one node on Public Testnet v1 that mines; with a seed node set, only
   once it is connected and caught up (`--mine-when-synced`).
2. **`--verifier`**: the same node without mining (`--no-mine`): it syncs, verifies and
   relays.
3. **`--local`**: a local dev net of three fully meshed mining nodes with a fresh genesis
   (`--seal-attempts 128 --target-block-secs 5 --blocks-per-epoch 12`) and explorers at
   <http://127.0.0.1:8081/>, <http://127.0.0.1:8082/> and <http://127.0.0.1:8083/>.
   Node `i` peers on `127.0.0.1:3034i` and keeps its data in `target/testnet/n<i>`; every
   run resets the chain data.

Every node creates its ML-DSA-87 miner key on its first run and loads it on every later
run; the launcher shows the key file and owner id before starting
(`plauthium-node key --data-dir DIR` does the same by hand). `--reset` wipes the chain
data but keeps the key. Ctrl-C stops the nodes gracefully.

Each explorer shows the 8 ledger categories with a live `Σ = M` check, the block feed and a
job-submission form. Jobs become fundable once the first epoch reward is paid into `U`, at
height `2 · blocks_per_epoch` (24 here). Before that, every atom of `U` is a locked founder
tranche.

To submit a commercial job from the command line (fees default to the WP 7.17 budget; the
node signs it with its miner key):

```sh
curl -s localhost:8081/api/submit_job -H 'content-type: application/json' \
  -d "{\"payload\":{\"type\":\"exact_dot\",\"xs\":[$(seq -s, 1 512)],\"ys\":[$(seq -s, 512 -1 1)]}}"
```

Other endpoints: `GET /api/status` and `GET /api/blocks?limit=20&before=<height>`. Run
`plauthium-node --help`, `plauthium-node genesis --help` and `plauthium-node run --help` for
the CLI.

## Public Testnet v1

All nodes built from this source share one genesis: `node/genesis.testnet.json`,
embedded in the binary, with `genesis_time_bucket` fixed at `1792540800`
(2026-10-21T00:00:00Z, the v1 launch). Its genesis id is

```text
2804064dac4e30a4cb47aa0d87c4da05427c6bcdb8d1d5aa45a1fd69c3677d5cd8d441d3beb877317277096139b6205287472d078dedea8e525be60ee5f5114e
```

and `node/tests/public_testnet.rs` fails if it changes. Retargeting never reads the
genesis time (its windows start at height `2 · window`), so a genesis in the past is
safe. `WIRE_VERSION` 4 puts the genesis id in the `Handshake`: a node on another genesis
(a local dev chain shares the `chain_id`) is not kept as a peer, and its dialer backs off
for 10 minutes.

The public node listens for peers on port 30333 (forward it to accept inbound peers) and
serves its explorer on `127.0.0.1:8080` only, since `/api/submit_job` pays with the miner
key. It dials the seed node named by `SEED_NODE_IP` (line 2 of `Plauthium_Testnet.sh`, or
the top of `scripts/testnet.sh`, or the environment) on port 30333. `--peer` takes
`IP:port` as well as `host:port`, re-resolved before every connection attempt. The
node's key is `~/.local/share/plauthium/miner_key.bin` and its chain data
`~/.local/share/plauthium/testnet-v1` (under `$XDG_DATA_HOME` if set, or
`$PLAUTHIUM_HOME`), outside the workspace, so `cargo clean` or a fresh copy of the script
keeps the identity. A node locks its data directory, so a second node on it refuses to
start. `PLAUTHIUM_MINING_THREADS` (default 1) and `PLAUTHIUM_RESET=1` (wipe the chain data,
keep the key) are optional.

`--mine-when-synced` keeps a node that cannot reach the network from mining a private
fork it could never leave: it mines only while a peer is connected, once its tip has
reached the best height its peers report, or once its tip has not moved for a minute
while connected. A peer's claimed height drops to what it delivers when a sync request to
it goes unanswered, or its answer is empty, starts at another height or brings nothing
new; gossip raises it to at most one block past our tip. So a peer cannot hold the gate
closed by claiming a height it does not have. A node with peers configured warns every
minute while none is connected.

**Seed nodes.** The first seed node runs `--miner` with `SEED_NODE_IP` empty, so it mines
alone from genesis. Everyone else sets `SEED_NODE_IP` to a running seed node's public IP.
A seed node that is given its own address drops the connection to itself (the
`Handshake` nonce), even behind 1:1 NAT.

## Verification limits (v1)

Stage B (context checks) needs no work, so a peer could otherwise make a node recompute
tiles for free. Limits apply per **source**: an IP address, the /64 prefix for IPv6, or
the full address for loopback peers (local testnets). Bans and the inbound cap of 16
connections are per source too.

- **Stage A slots:** at most 2 blocks of a source in Stage A, 16 in total. A block that
  passes Stage B beyond that waits in a FIFO queue: at most 8 per source and 64 in total.
  A newly arrived block over these limits gets `Busy`: not remembered, nobody penalized,
  and net asks that peer again 2 s later. When the queue is full, the newest entry of the
  source holding the most (clearly more than the newcomer's) makes room. Parked children
  and deferred blocks released for verification are not refused.
- **Order:** signatures, then the header's tile, then the share tiles. A block's share
  tiles are only recomputed once its seal is known to be genuine work.
- **Cancellation:** when a block or share of a source fails verification, the chain actor
  bans the source on the spot: its other Stage A tasks are aborted (a tile already
  computing finishes, as it cannot be interrupted, and its result is discarded) and its
  queued, parked and deferred blocks, share checks and parked shares are dropped. Nothing
  new from it is admitted until the ban ends; net closes its connections and sends the
  same cancellation for bans of its own (protocol violations). Semaphore permits stay with
  the computation, so aborted work never lets more tiles run than `--verify-threads`.
- **Second senders:** each pending block remembers up to 3 other sources that delivered
  the same bytes. A block whose first sender is banned stays pending (a running Stage A
  goes on) for one of them, since honest peers relay a block only once.
- **Settled only:** net remembers a block or share as seen only once it is accepted or
  rejected, so copies of pending ones still reach the chain actor (a cheap duplicate
  check, which records the second sender).
- **Parked orphans** (parent not yet known; they cost nothing to make): at most 64 per
  source, a full sync batch, and 256 in total. A source over its share evicts its own
  oldest orphan; a full set evicts the oldest of the source holding the most.
- **Deferred blocks** (time bucket ahead of the local clock): at most 8 per source and 64
  in total, and none more than 75 s ahead. Orphans released by their parent count too.
- **Errors** of the verification machinery itself (a panicked or cancelled task) drop the
  block or share without penalizing anyone.
- **Jobs:** the mempool also refuses a copy of a job that is already on the canonical
  chain (until it expires), so replaying old jobs cannot fill it.

The RPC reports these counters under `verification` in `GET /api/status`.

## Owner identity (v1)

An owner is an ML-DSA-87 key pair (FIPS 204, RustCrypto `ml-dsa`), stored as its 32-byte
seed. Its **key id** is `H(PLAU/TESTNET/OWNER/v1, public key)`.

- **On the wire:** `BlockHeader.miner_key`, `ShareProof.owner_key` and
  `JobTransaction.client_key` carry the 2,592-byte public key. Each object ends with a
  4,627-byte `signature` over a domain-separated digest of all its other fields:
  `PLAU/TESTNET/SIG/{HEADER,SHARE,JOB}/v1`. The job digest also binds `genesis_id`, and
  every signature uses the FIPS 204 context string `PLAU/TX/v2`.
- **Bound to the work:** context fields 11 and 12 are `H(PLAU/TESTNET/{MINER,PAYOUT}/v2,
  key id)`. Re-signing someone else's block or share under another key breaks Stage B.
- **Verified before the STF:** Stage A checks every signature before any tile is
  recomputed. `apply_body` only accepts a `VerifiedOwner`, which `chain::core_adapter` alone
  can create, after a successful verification.
- **Bridged to the frozen core:** the scheduler's `OwnerId(u64)` is the first 8 bytes of
  the key id. It only bounds owner capacity. Rewards (`OwnerReward`), leases and receipts
  carry the full 512-bit key id.
- **Stable job identity:** `tx_id` hashes the job without its signature, so re-signing never
  changes a job's identity.
- **Relay ids:** `block_id` and `tx_id` leave out signatures, so anyone can forge an invalid
  copy that shares an honest object's id. The node's relay and rejection caches therefore
  key on a hash of the full signed encoding (`chain::block_relay_id`, `chain::job_relay_id`),
  and a forged copy cannot shadow the genuine block or job. A block's relay id covers its
  body as well, so a genuine header carrying a forged body cannot shadow the block either.

`crypto_suite_id` is 1 (SHA3-512 + SHAKE256 + ML-DSA-87).

## Share gossip (v1)

`WIRE_VERSION` 3 adds `GossipShare(ShareProof)`. Every node keeps a share pool (`node::share_pool`)
of verified shares, its own and gossiped ones, one per `work_id`. Templates take up to
`max_shares_per_block` of them, whoever mined them, oldest height first, and emit them sorted by
`work_id`, so a share counts for rewards and leases even if its owner never seals a block.

A gossiped share enters the pool, and is relayed onward, only after every check passes,
cheapest first:

1. Dedupe: by relay id (`chain::share_relay_id`, the full signed encoding), by `work_id`
   against the pool (work-checked shares only), and by (owner key id, `work_id`) against
   shares still awaiting their work check. A slot is only taken once the owner signature
   verified, so a forged copy, or a claim to another owner's `work_id`, cannot shadow the
   genuine share, and re-signed copies (ML-DSA signing is randomized) cost nothing.
2. No-work checks (`BlockTree::check_gossip_share`): context constants, owner binding,
   height, anchor and target on the share's own branch, inclusion window, not yet
   registered.
3. Limits on shares awaiting their work check: 8 per source, 64 in total.
4. The ML-DSA-87 signature, checked on the spot.
5. Its tile, recomputed off the chain actor on a separate, smaller verification budget,
   so a block's Stage A never queues behind share gossip.

A share whose parent block is in Stage A waits for it (signature already checked, counted
in the limits), and is dropped if that block fails. Such a share, a stale one and one whose
parent is unknown are dropped without penalty and not remembered as seen, so a later relay
can still deliver them. Useless shares (ignored for any reason, including the limits above,
or duplicates under a new encoding) are budgeted at 256 a minute per peer; past that, the
peer's shares are dropped unread until the minute is up. The peer is throttled, not banned,
since an honest peer that is syncing sends many such shares. A peer that sends an invalid
share is banned, even if it disconnected first, and a ban closes every connection from its
source (see [Verification limits](#verification-limits-v1)). A dialer backs off unless the
connection lasts a minute, so a peer that drops it at once is not redialed every second.

Templates include only fully verified shares, and `validate_genesis` requires every block
to fit a full set of `max_shares_per_block` shares plus 16 KiB of headroom. The pool is
pruned when shares leave the inclusion window or are registered on the canonical chain,
and the shares of abandoned blocks return to it on a reorg.

## Known gaps (blueprint §1.2)

Gaps 1 (placeholder hashing), 2 (self-declared integer owners, no signatures) and 4 (shares
not gossiped) are closed in v1. The numbering of the remaining gaps follows the blueprint.

- **Shared faucet.** The core ledger has no per-account balances (see
  `ledger/src/lib.rs` lines 18–21), so a job's signature authenticates its client, but its
  deposit is debited from the aggregate `U`.

3. **VerifyFW by recomputation.** Validators recompute every claimed tile instead of
   verifying a Circle STARK. There is no P-DAL (Reed–Solomon layer).
5. **Commercial execution is replicated.** Every validator recomputes each job's result.
   The lessee is the executor by attribution only. Commercial weight stays 0
   (`scivm::CONSENSUS_WEIGHT`).
6. **No refunds or timeouts.** The core ledger has no `ESCROW_REFUND` or `LEASE_TIMEOUT`,
   so every admitted job settles deterministically after `settle_delay` blocks.
7. **Founder vesting is tied to `BLOCKS_PER_DAY = 720` blocks**, regardless of the testnet
   block time.
8. **State only grows.** Fee lots are never pruned by the core, and every block stays in
   memory, so memory grows with chain length and job count.

## Core adapter (blueprint §13.2 A1)

The core math is unchanged. `primitives` gained one additive method, and v1 swapped its
hash backend to SHA3-512/SHAKE256 behind the same interface (the XOF type is now
`Shake256Xof`, formerly `MockXof`):

```rust
impl DomainSeparatedHash {
    /// The digest bytes by value; inverse of [`DomainSeparatedHash::from_bytes`].
    pub const fn to_bytes(&self) -> [u8; DIGEST_LEN] { self.0 }
}
```

`from_bytes` and `as_bytes` already existed. Every conversion between wire digests and core
hashes lives in `chain::core_adapter`, and so does the bridge from verified ML-DSA-87 keys
to the scheduler's `OwnerId`.

## PoC placeholders in the core

- **Hashing (real since v1):** `DomainSeparatedHash` is SHA3-512 and `Shake256Xof` is
  SHAKE256, both over the normative encoding: a domain label, an injective length-prefixed
  encoding, and 64-byte digests.
- **Signatures:** ML-DSA-87 lives in the `chain` crate since v1. The core crates take only the
  derived `OwnerId`.
- **Not implemented:** SLH-DSA, ML-KEM, the Circle STARK, P-DAL and zk-TWL notes.
- **Share weights:** `ShareWeight` is `u64`. The normative `w_s = ⌊2^640/Θ_S⌋` needs a bignum.
  With `u64` weights, every D'Hondt and payout cross-product is exact in `u128`.
- **Aggregate balances:** `U`, `S_z`, `B_bond` and `V_L2` hold totals only, with no per-UTXO
  ownership.
- **Deployment parameters:** epoch length, maturation delay `L`, `η` and fee tariffs are
  illustrative values in `LedgerParams::poc()`. The testnet takes them from its genesis file.

## Ledger category mapping

The 8 categories are the ones in eq. (7.19). `FounderAllocation` and `MatureFeeLots` are
sub-ledgers, not extra balances. The spec says vesting "adds no ninth balance", and matured
lots live in `R_a`.

| Variant           | Symbol      | Holds |
|-------------------|-------------|-------|
| `Circulating`     | `U`         | public UTXOs, incl. the 1,460 founder tranches |
| `ShieldedPool`    | `S_z`       | shielded notes |
| `Escrow`          | `E_esc`     | per-job escrows |
| `Bonds`           | `B_bond`    | executor bonds |
| `L2Vaults`        | `V_L2`      | rollup settlement vaults |
| `EmissionReserve` | `R_a`       | Genesis emission lot + mature fee lots + segregated dust |
| `LockedBaseFees`  | `R_l`       | Base Fees and queue fees awaiting maturation |
| `PendingRewards`  | `P_pending` | booked, unpaid Fresh Work rewards |
EOF

cat << 'EOF' > chain/Cargo.toml
[package]
name = "chain"
version = "0.1.0"
edition = "2024"
description = "Plauthium Testnet synchronous chain logic: genesis, STF, VerifyFW, difficulty, and BlockTree"

[dependencies]
primitives = { workspace = true }
work = { workspace = true }
scivm = { workspace = true }
scheduler = { workspace = true }
ledger = { workspace = true }
wire = { workspace = true }
ml-dsa = { workspace = true }

[lints]
workspace = true
EOF

cat << 'EOF' > chain/src/core_adapter.rs
//! Core adapter (§3.3, §5.4, §5.8, §5.9, §6.1, §6.2, §13).
//!
//! The only module that converts between wire types and the frozen core crates. It is
//! also where owner identity crosses into the core: an ML-DSA-87 signature is verified
//! here before the owner's key id and its 64-bit `scheduler::OwnerId` reach `apply_body`.

use core::fmt;
use std::sync::{Arc, Mutex, OnceLock};

use ledger::{EmissionRate, Ledger, LedgerParams};
use ml_dsa::{EncodedSignature, EncodedVerifyingKey, MlDsa87, VerifyingKey};
use primitives::{DomainSeparatedHash, labels, pq_sizes};
use scivm::{OzakiIIProfile, RoundingMode};
use wire::{
    Block, BlockBody, BlockHeader, DOT_LEN, Digest, ENCODED_HEADER_LEN, ENCODED_SHARE_LEN,
    FwContext, GenesisConfig, JobPayload, JobTransaction, MAX_JOB_BYTES, MIN_TARGET,
    PUBLIC_KEY_LEN, PublicKey, SIGNATURE_LEN, ShareProof, Signature, Target, codec,
};

/// Bytes `validate_genesis` requires beyond the header and a full set of shares: room
/// for the body's framing (vector lengths, `ledger_digest`) and its derived fields.
pub const BLOCK_HEADROOM: u64 = 16_384;
use work::{FreshWorkContext, FreshWorkIds, TILE_DIM};

// ---------------------------------------------------------------------------
// Domain labels (§3.3)
// ---------------------------------------------------------------------------

/// Label of `genesis_id`.
pub const LABEL_GENESIS: &str = "PLAU/TESTNET/GENESIS/v1";
/// Label of the `program_id` and `air_id` tags.
pub const LABEL_TAG: &str = "PLAU/TESTNET/TAG/v1";
/// Label of `miner_policy_digest` (v2: hashes the owner key id).
pub const LABEL_MINER: &str = "PLAU/TESTNET/MINER/v2";
/// Label of `payout_policy_digest` (v2: hashes the owner key id).
pub const LABEL_PAYOUT: &str = "PLAU/TESTNET/PAYOUT/v2";
/// Label of `parent_derived_difficulty_context`.
pub const LABEL_DIFFICULTY: &str = "PLAU/TESTNET/DIFFICULTY/v1";
/// Label of `body_core_root`.
pub const LABEL_BODY: &str = "PLAU/TESTNET/BODY/v1";
/// Label of `tx_id` (v2: hashes the encoding without the signature).
pub const LABEL_JOB: &str = "PLAU/TESTNET/JOB/v2";
/// Label of an owner key id, `H(PLAU/TESTNET/OWNER/v1, public key)`.
pub const LABEL_OWNER: &str = "PLAU/TESTNET/OWNER/v1";
/// Label of the digest a client signs for a job.
pub const LABEL_SIG_JOB: &str = "PLAU/TESTNET/SIG/JOB/v1";
/// Label of the digest an owner signs for a share proof.
pub const LABEL_SIG_SHARE: &str = "PLAU/TESTNET/SIG/SHARE/v1";
/// Label of the digest a miner signs for a block header.
pub const LABEL_SIG_HEADER: &str = "PLAU/TESTNET/SIG/HEADER/v1";
/// FIPS 204 context string of every ML-DSA-87 signature (spec eqs. 2.3–2.5).
pub const SIGNATURE_CONTEXT: &[u8] = labels::PLAU_TX.as_bytes();
/// Label of a block's relay id (local, not consensus).
pub const LABEL_RELAY_BLOCK: &str = "PLAU/TESTNET/RELAY/BLOCK/v1";
/// Label of a job's relay id (local, not consensus).
pub const LABEL_RELAY_JOB: &str = "PLAU/TESTNET/RELAY/JOB/v1";
/// Label of a share proof's relay id (local, not consensus).
pub const LABEL_RELAY_SHARE: &str = "PLAU/TESTNET/RELAY/SHARE/v1";
/// Label of `ledger_digest`.
pub const LABEL_LEDGER: &str = "PLAU/TESTNET/LEDGER/v1";
/// Label of `result_digest`.
pub const LABEL_RESULT: &str = "PLAU/TESTNET/RESULT/v1";

/// Tag name hashed into `program_id`.
pub const PROGRAM_TAG_NAME: &str = "program/fresh-work-int8-512";
/// Tag name hashed into `air_id`.
pub const AIR_TAG_NAME: &str = "air/int8-tile";

const _: () = assert!(DOT_LEN == TILE_DIM);
const _: () = assert!(wire::DIGEST_LEN == primitives::DIGEST_LEN);
const _: () = assert!(PUBLIC_KEY_LEN as u64 == pq_sizes::ML_DSA_87_PUBLIC_KEY);
const _: () = assert!(SIGNATURE_LEN as u64 == pq_sizes::ML_DSA_87_SIGNATURE);

/// Converts a core `DomainSeparatedHash` into a wire `Digest`.
pub fn hash_to_digest(h: &DomainSeparatedHash) -> Digest {
    Digest(h.to_bytes())
}

/// Converts a wire `Digest` into a core `DomainSeparatedHash`.
pub fn digest_to_hash(d: &Digest) -> DomainSeparatedHash {
    DomainSeparatedHash::from_bytes(d.0)
}

/// Computes a domain-separated digest using `primitives::DomainSeparatedHash::new`.
pub fn domain_hash(label: &str, parts: &[&[u8]]) -> Digest {
    hash_to_digest(&DomainSeparatedHash::new(label, parts))
}

/// Computes `genesis_id = H(PLAU/TESTNET/GENESIS/v1, codec(GenesisConfig))`.
pub fn compute_genesis_id(config: &GenesisConfig) -> Result<Digest, String> {
    let bytes = codec::encode(config).map_err(|e| e.to_string())?;
    Ok(domain_hash(LABEL_GENESIS, &[&bytes]))
}

/// Computes `(program_id, air_id)` from §3.3.
pub fn compute_program_and_air_ids() -> (Digest, Digest) {
    let program_id = domain_hash(LABEL_TAG, &[PROGRAM_TAG_NAME.as_bytes()]);
    let air_id = domain_hash(LABEL_TAG, &[AIR_TAG_NAME.as_bytes()]);
    (program_id, air_id)
}

/// Computes `miner_policy_digest = H(PLAU/TESTNET/MINER/v2, owner_key_id)`.
pub fn compute_miner_policy_digest(owner_key_id: &Digest) -> Digest {
    domain_hash(LABEL_MINER, &[&owner_key_id.0])
}

/// Computes `payout_policy_digest = H(PLAU/TESTNET/PAYOUT/v2, owner_key_id)`.
pub fn compute_payout_policy_digest(owner_key_id: &Digest) -> Digest {
    domain_hash(LABEL_PAYOUT, &[&owner_key_id.0])
}

/// Computes `parent_derived_difficulty_context = H(PLAU/TESTNET/DIFFICULTY/v1, seal_target, share_target)`.
pub fn compute_difficulty_context(seal_target: Target, share_target: Target) -> Digest {
    domain_hash(
        LABEL_DIFFICULTY,
        &[&seal_target.0.to_be_bytes(), &share_target.0.to_be_bytes()],
    )
}

/// Computes `body_core_root = H(PLAU/TESTNET/BODY/v1, codec(BlockBody))`.
pub fn compute_body_root(body: &BlockBody) -> Result<Digest, String> {
    let bytes = codec::encode(body).map_err(|e| e.to_string())?;
    Ok(domain_hash(LABEL_BODY, &[&bytes]))
}

/// `(tx_id, job_id)` from the encoded transaction bytes.
fn job_ids_from_encoding(encoded: &[u8]) -> (Digest, u64) {
    let tx_id = domain_hash(LABEL_JOB, &[encoded]);
    let mut first8 = [0u8; 8];
    first8.copy_from_slice(&tx_id.0[..8]);
    (tx_id, u64::from_be_bytes(first8))
}

/// Computes `(tx_id, job_id)` for a `JobTransaction` (§5.4). `tx_id` hashes the
/// encoding without the signature, so re-signing a job never changes its identity.
pub fn compute_job_ids(tx: &JobTransaction) -> Result<(Digest, u64), String> {
    let bytes = tx.unsigned_encoding().map_err(|e| e.to_string())?;
    Ok(job_ids_from_encoding(&bytes))
}

/// Computes `result_digest = H(PLAU/TESTNET/RESULT/v1, job_id, result)`.
pub fn compute_result_digest(job_id: u64, result: i128) -> Digest {
    domain_hash(
        LABEL_RESULT,
        &[&job_id.to_be_bytes(), &result.to_be_bytes()],
    )
}

/// Extracts the most-significant 128 bits of a digest (§6.1).
pub fn top128(d: &Digest) -> u128 {
    let mut buf = [0u8; 16];
    buf.copy_from_slice(&d.0[..16]);
    u128::from_be_bytes(buf)
}

// ---------------------------------------------------------------------------
// Genesis validation (§3.2, §3.4)
// ---------------------------------------------------------------------------

/// Validates a `GenesisConfig` and returns its `LedgerParams`, the genesis `Ledger`
/// and `genesis_id`.
pub fn validate_genesis(config: &GenesisConfig) -> Result<(LedgerParams, Ledger, Digest), String> {
    if config.share_ratio < 1 {
        return Err("share_ratio must be >= 1".to_string());
    }
    if config.initial_seal_target.0 < MIN_TARGET {
        return Err("initial_seal_target must be >= MIN_TARGET".to_string());
    }
    if config.time_bucket_secs < 1 {
        return Err("time_bucket_secs must be >= 1".to_string());
    }
    if config.target_block_secs < config.time_bucket_secs
        || !config
            .target_block_secs
            .is_multiple_of(config.time_bucket_secs)
    {
        return Err(
            "target_block_secs must be >= time_bucket_secs and a multiple of time_bucket_secs"
                .to_string(),
        );
    }
    if config.blocks_per_epoch < 1 {
        return Err("blocks_per_epoch must be >= 1".to_string());
    }
    if config.anchor_depth < 1 {
        return Err("anchor_depth must be >= 1".to_string());
    }
    if config.settle_delay < 1 {
        return Err("settle_delay must be >= 1".to_string());
    }
    if config.share_maturity_depth < 1 || config.share_maturity_depth >= config.snapshot_window {
        return Err("must satisfy 1 <= share_maturity_depth < snapshot_window".to_string());
    }
    if config.share_inclusion_window < 1 {
        return Err("share_inclusion_window must be >= 1".to_string());
    }
    if let wire::DifficultyMode::Windowed { window } = config.difficulty
        && window < 2
    {
        return Err("retarget window must be >= 2 when Windowed".to_string());
    }
    // A full set of shares must always fit, or a template holding them (every node
    // picks the same gossiped shares) would be too large to be a valid block.
    let full_shares = config
        .max_shares_per_block
        .checked_mul(ENCODED_SHARE_LEN as u64)
        .and_then(|b| b.checked_add(ENCODED_HEADER_LEN as u64 + BLOCK_HEADROOM));
    if full_shares.is_none_or(|need| need > config.max_block_bytes) {
        return Err(format!(
            "max_block_bytes must hold the header, max_shares_per_block shares of {ENCODED_SHARE_LEN} bytes and {BLOCK_HEADROOM} bytes of headroom"
        ));
    }

    let emission_rate = EmissionRate::new(config.emission_numerator, config.emission_denominator)
        .map_err(|e| e.to_string())?;
    let params = LedgerParams {
        genesis_height: 0,
        blocks_per_epoch: config.blocks_per_epoch,
        maturation_delay: config.maturation_delay,
        emission_rate,
    };
    let ledger = Ledger::genesis(params).map_err(|e| e.to_string())?;
    let genesis_id = compute_genesis_id(config)?;
    Ok((params, ledger, genesis_id))
}

// ---------------------------------------------------------------------------
// SciVM Ozaki-II profile & stateless job validation (§5.4)
// ---------------------------------------------------------------------------

/// Returns the normative `TESTNET_PROFILE`, the literal of `poc/src/main.rs` lines 133–140 (§5.4).
pub fn testnet_ozaki_profile() -> OzakiIIProfile {
    OzakiIIProfile {
        version: 1,
        moduli: vec![255, 254, 253, 251, 247, 241, 239, 233],
        inner_dim: TILE_DIM as u64,
        bound_x: 1 << 23,
        bound_y: 1 << 23,
        rounding: RoundingMode::NearestTiesToEven,
    }
}

/// Error returned during stateless job validation.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum JobValidationError {
    /// A fee that must be positive is zero (names the field).
    ZeroFee(&'static str),
    /// `deposit` or the total charge overflows `u64`.
    AmountOverflow,
    /// The encoded job is larger than `MAX_JOB_BYTES`.
    TooLarge(usize),
    /// The payload is malformed or rejected by the SciVM profile.
    InvalidPayload(String),
}

impl fmt::Display for JobValidationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            JobValidationError::ZeroFee(field) => write!(f, "{field} must be > 0"),
            JobValidationError::AmountOverflow => write!(f, "fee/deposit addition overflowed u64"),
            JobValidationError::TooLarge(len) => {
                write!(
                    f,
                    "encoded job size {len} exceeds MAX_JOB_BYTES ({MAX_JOB_BYTES})"
                )
            }
            JobValidationError::InvalidPayload(msg) => write!(f, "invalid payload: {msg}"),
        }
    }
}

impl std::error::Error for JobValidationError {}

/// Validates a `JobTransaction` statelessly (§5.4) and returns
/// `(tx_id, job_id, deposit, exact_dot)`.
pub fn validate_job_stateless(
    tx: &JobTransaction,
) -> Result<(Digest, u64, u64, i128), JobValidationError> {
    if tx.queue_fee == 0 {
        return Err(JobValidationError::ZeroFee("queue_fee"));
    }
    if tx.base_fee == 0 {
        return Err(JobValidationError::ZeroFee("base_fee"));
    }
    if tx.v_exec == 0 {
        return Err(JobValidationError::ZeroFee("v_exec"));
    }
    let deposit = tx
        .checked_deposit()
        .ok_or(JobValidationError::AmountOverflow)?;
    tx.checked_total_charge()
        .ok_or(JobValidationError::AmountOverflow)?;

    let encoded = codec::encode(tx)
        .map_err(|e| JobValidationError::InvalidPayload(format!("codec failed: {e}")))?;
    if encoded.len() > MAX_JOB_BYTES {
        return Err(JobValidationError::TooLarge(encoded.len()));
    }
    // `tx_id` hashes the bytes without the trailing signature, as in `compute_job_ids`.
    let unsigned_len = encoded.len() - SIGNATURE_LEN;

    let dot = match &tx.payload {
        JobPayload::ExactDot { xs, ys } => {
            if xs.len() != DOT_LEN || ys.len() != DOT_LEN {
                return Err(JobValidationError::InvalidPayload(format!(
                    "ExactDot requires {DOT_LEN} operands per vector, got ({}, {})",
                    xs.len(),
                    ys.len()
                )));
            }
            if xs
                .iter()
                .chain(ys)
                .any(|v| !v.is_finite() || v.fract() != 0.0)
            {
                return Err(JobValidationError::InvalidPayload(
                    "every operand must be finite with zero fractional part".to_string(),
                ));
            }
            testnet_ozaki_profile()
                .exact_dot(xs, ys)
                .map_err(|e| JobValidationError::InvalidPayload(e.to_string()))?
        }
    };

    let (tx_id, job_id) = job_ids_from_encoding(&encoded[..unsigned_len]);
    Ok((tx_id, job_id, deposit, dot))
}

// ---------------------------------------------------------------------------
// Owner identity: key ids, signing digests and ML-DSA-87 verification
// ---------------------------------------------------------------------------

/// Computes an owner key id, `H(PLAU/TESTNET/OWNER/v1, public key)`.
pub fn owner_key_id(key: &PublicKey) -> Digest {
    domain_hash(LABEL_OWNER, &[&key.as_bytes()[..]])
}

/// Narrows a key id to the 64-bit `scheduler::OwnerId` (its first 8 bytes, big-endian).
///
/// The frozen scheduler uses this only for owner capacity bounds. Rewards, leases
/// and receipts carry the full 512-bit key id, so a colliding 64-bit value (about
/// 2^32 key generations) cannot redirect funds or attributions.
pub fn owner_id_from_key_id(key_id: &Digest) -> u64 {
    let mut first8 = [0u8; 8];
    first8.copy_from_slice(&key_id.0[..8]);
    u64::from_be_bytes(first8)
}

/// The digest a client signs: `H(PLAU/TESTNET/SIG/JOB/v1, genesis_id, tx_id)`.
///
/// `tx_id` covers every field but the signature; `genesis_id` stops a job signed for
/// one testnet from being replayed on another.
pub fn job_signing_digest(tx: &JobTransaction, genesis_id: &Digest) -> Result<Digest, String> {
    let (tx_id, _) = compute_job_ids(tx)?;
    Ok(domain_hash(LABEL_SIG_JOB, &[&genesis_id.0, &tx_id.0]))
}

/// The digest an owner signs: `H(PLAU/TESTNET/SIG/SHARE/v1, unsigned share encoding)`.
/// The context inside binds the chain and the genesis.
pub fn share_signing_digest(share: &ShareProof) -> Result<Digest, String> {
    let bytes = share.unsigned_encoding().map_err(|e| e.to_string())?;
    Ok(domain_hash(LABEL_SIG_SHARE, &[&bytes]))
}

/// The digest a miner signs: `H(PLAU/TESTNET/SIG/HEADER/v1, unsigned header encoding)`.
pub fn header_signing_digest(header: &BlockHeader) -> Result<Digest, String> {
    let bytes = header.unsigned_encoding().map_err(|e| e.to_string())?;
    Ok(domain_hash(LABEL_SIG_HEADER, &[&bytes]))
}

/// Signature verification error.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SignatureError {
    /// The signed object could not be encoded.
    Encoding(String),
    /// The signature bytes are not a valid ML-DSA-87 encoding (FIPS 204 `sigDecode`).
    Malformed,
    /// ML-DSA-87 verification failed.
    Invalid,
}

impl fmt::Display for SignatureError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SignatureError::Encoding(msg) => write!(f, "cannot encode the signed object: {msg}"),
            SignatureError::Malformed => write!(f, "malformed ML-DSA-87 signature"),
            SignatureError::Invalid => write!(f, "ML-DSA-87 signature verification failed"),
        }
    }
}

impl std::error::Error for SignatureError {}

/// Relay id of a block: a hash of its full encoding, header (signature included) and
/// body, so it names the exact block bytes.
///
/// `block_id` leaves out the signature (and other claimed fields), so anyone can make
/// an invalid copy that shares an honest block's `block_id`. Relay and rejection
/// caches must key on this id, or such a copy would shadow the genuine block. The body
/// is hashed too: `body_core_root` binds it only once checked, so a genuine header
/// with a forged body must not share the genuine block's relay id either.
pub fn block_relay_id(block: &Block) -> Result<Digest, String> {
    let bytes = codec::encode(block).map_err(|e| e.to_string())?;
    Ok(domain_hash(LABEL_RELAY_BLOCK, &[&bytes]))
}

/// Relay id of a job: a hash of its full encoding, signature included. Relay caches
/// key on it for the reason given at [`block_relay_id`]; the mempool and the chain
/// keep deduplicating by `tx_id`.
pub fn job_relay_id(tx: &JobTransaction) -> Result<Digest, String> {
    let bytes = codec::encode(tx).map_err(|e| e.to_string())?;
    Ok(domain_hash(LABEL_RELAY_JOB, &[&bytes]))
}

/// Relay id of a share proof: a hash of its full encoding, signature included. Relay
/// and rejection caches key on it for the reason given at [`block_relay_id`]; the
/// share pool keeps one share per `work_id`.
pub fn share_relay_id(share: &ShareProof) -> Result<Digest, String> {
    let bytes = codec::encode(share).map_err(|e| e.to_string())?;
    Ok(domain_hash(LABEL_RELAY_SHARE, &[&bytes]))
}

/// An owner whose ML-DSA-87 signature over a specific object has been verified.
///
/// Only [`verify_share_owner`], [`verify_header_miner`] and [`verify_job_client`]
/// create one, each from the signature on its own object, so a `VerifiedOwner` cannot
/// be minted from a signature over some unrelated digest.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct VerifiedOwner {
    key_id: Digest,
    owner_id: u64,
}

impl VerifiedOwner {
    /// The owner key id, `H(PLAU/TESTNET/OWNER/v1, public key)`.
    pub fn key_id(&self) -> Digest {
        self.key_id
    }

    /// The 64-bit `scheduler::OwnerId` derived from the key id.
    pub fn owner_id(&self) -> u64 {
        self.owner_id
    }
}

/// Decoded verifying keys kept by [`verify_ml_dsa_87`], most recently used last.
const KEY_CACHE_CAPACITY: usize = 64;

type KeyCache = Mutex<Vec<(Digest, Arc<VerifyingKey<MlDsa87>>)>>;

/// The decoded verifying key for `key`, whose key id is `key_id`.
///
/// Decoding (FIPS 204 `pkDecode` plus `ExpandA`) costs about two thirds of a
/// verification, and a testnet has few distinct signers, so recently used keys are
/// cached. Entries are keyed by the SHA3-512 key id of the encoded key.
fn decoded_key(key_id: &Digest, key: &PublicKey) -> Arc<VerifyingKey<MlDsa87>> {
    static CACHE: OnceLock<KeyCache> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(Vec::with_capacity(KEY_CACHE_CAPACITY)));
    {
        let mut entries = cache.lock().unwrap_or_else(|e| e.into_inner());
        if let Some(pos) = entries.iter().position(|(id, _)| id == key_id) {
            let entry = entries.remove(pos);
            let decoded = entry.1.clone();
            entries.push(entry);
            return decoded;
        }
    }
    let encoded = EncodedVerifyingKey::<MlDsa87>::try_from(&key.as_bytes()[..])
        .expect("invariant: a PublicKey holds exactly 2,592 bytes");
    let decoded = Arc::new(VerifyingKey::<MlDsa87>::decode(&encoded));
    let mut entries = cache.lock().unwrap_or_else(|e| e.into_inner());
    if !entries.iter().any(|(id, _)| id == key_id) {
        if entries.len() >= KEY_CACHE_CAPACITY {
            entries.remove(0);
        }
        entries.push((*key_id, decoded.clone()));
    }
    decoded
}

/// Checks an ML-DSA-87 signature (FIPS 204 `ML-DSA.Verify` with context
/// [`SIGNATURE_CONTEXT`]) over a domain-separated `digest`.
///
/// This is the raw check. Code that needs an owner identity uses the object-specific
/// verifiers below, which are the only way to obtain a [`VerifiedOwner`].
pub fn verify_ml_dsa_87(
    key: &PublicKey,
    digest: &Digest,
    signature: &Signature,
) -> Result<(), SignatureError> {
    verify_owner_signature(key, digest, signature).map(|_| ())
}

/// Verifies `signature` and, only on success, returns the signer's key id and
/// derived `OwnerId`.
fn verify_owner_signature(
    key: &PublicKey,
    digest: &Digest,
    signature: &Signature,
) -> Result<VerifiedOwner, SignatureError> {
    let encoded_sig = EncodedSignature::<MlDsa87>::try_from(&signature.as_bytes()[..])
        .map_err(|_| SignatureError::Malformed)?;
    let sig =
        ml_dsa::Signature::<MlDsa87>::decode(&encoded_sig).ok_or(SignatureError::Malformed)?;
    let key_id = owner_key_id(key);
    if !decoded_key(&key_id, key).verify_with_context(&digest.0, SIGNATURE_CONTEXT, &sig) {
        return Err(SignatureError::Invalid);
    }
    Ok(VerifiedOwner {
        key_id,
        owner_id: owner_id_from_key_id(&key_id),
    })
}

/// Verifies a share proof's owner signature.
pub fn verify_share_owner(share: &ShareProof) -> Result<VerifiedOwner, SignatureError> {
    let digest = share_signing_digest(share).map_err(SignatureError::Encoding)?;
    verify_owner_signature(&share.owner_key, &digest, &share.signature)
}

/// Verifies a block header's miner signature.
pub fn verify_header_miner(header: &BlockHeader) -> Result<VerifiedOwner, SignatureError> {
    let digest = header_signing_digest(header).map_err(SignatureError::Encoding)?;
    verify_owner_signature(&header.miner_key, &digest, &header.signature)
}

/// Verifies a job's client signature for the chain with `genesis_id`.
pub fn verify_job_client(
    tx: &JobTransaction,
    genesis_id: &Digest,
) -> Result<VerifiedOwner, SignatureError> {
    let digest = job_signing_digest(tx, genesis_id).map_err(SignatureError::Encoding)?;
    verify_owner_signature(&tx.client_key, &digest, &tx.signature)
}

// ---------------------------------------------------------------------------
// Fresh Work conversions and Stage A verification (§5.9, §6.2)
// ---------------------------------------------------------------------------

/// Converts a wire `FwContext` to `work::FreshWorkContext`; integer fields that do not fit
/// the core widths make the context invalid.
pub fn fw_context_to_core(ctx: &FwContext) -> Result<FreshWorkContext, WorkError> {
    Ok(FreshWorkContext {
        chain_id: ctx.chain_id,
        genesis_id: digest_to_hash(&ctx.genesis_id),
        protocol_version: ctx
            .protocol_version
            .try_into()
            .map_err(|_| WorkError::ContextFieldOverflow("protocol_version"))?,
        crypto_suite_id: ctx
            .crypto_suite_id
            .try_into()
            .map_err(|_| WorkError::ContextFieldOverflow("crypto_suite_id"))?,
        program_id: digest_to_hash(&ctx.program_id),
        air_id: digest_to_hash(&ctx.air_id),
        generator_version: ctx
            .generator_version
            .try_into()
            .map_err(|_| WorkError::ContextFieldOverflow("generator_version"))?,
        parent_canonical_id: digest_to_hash(&ctx.parent_canonical_id),
        stable_anchor_id: digest_to_hash(&ctx.stable_anchor_id),
        height: ctx.height,
        miner_policy_digest: digest_to_hash(&ctx.miner_policy_digest),
        payout_policy_digest: digest_to_hash(&ctx.payout_policy_digest),
        attempt_nonce: ctx.attempt_nonce,
        body_core_root: digest_to_hash(&ctx.body_core_root),
        parent_derived_difficulty_context: digest_to_hash(&ctx.parent_derived_difficulty_context),
        time_bucket: ctx.time_bucket,
    })
}

/// Fresh Work outputs as wire digests.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct WorkDigests {
    /// `outputRoot`.
    pub output_root: Digest,
    /// `WorkID`, which is also the ShareID.
    pub work_id: Digest,
    /// `BlockID`.
    pub block_id: Digest,
    /// `θ_S`.
    pub share_ticket: Digest,
    /// `θ_B`.
    pub seal_ticket: Digest,
}

/// Converts `work::FreshWorkIds` into wire digests.
pub fn fresh_work_ids_to_digests(ids: &FreshWorkIds) -> WorkDigests {
    WorkDigests {
        output_root: hash_to_digest(&ids.output_root),
        work_id: hash_to_digest(&ids.work_id),
        block_id: hash_to_digest(&ids.block_id),
        share_ticket: hash_to_digest(&ids.share_ticket),
        seal_ticket: hash_to_digest(&ids.seal_ticket),
    }
}

/// Evaluates one Fresh Work attempt: instance, 512^3 product and identifiers (§5.2).
pub fn evaluate_fresh_work(ctx: &FwContext) -> Result<WorkDigests, WorkError> {
    let core_ctx = fw_context_to_core(ctx)?;
    let inst = core_ctx.instance();
    let z = inst.x.product(&inst.y);
    Ok(fresh_work_ids_to_digests(&FreshWorkIds::derive(
        &core_ctx, &z,
    )))
}

/// Lottery mode for Stage A verification.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Lottery {
    /// Header seal: checks `block_id` and `θ_B < Θ_B`.
    Seal,
    /// Share proof: checks `θ_S < Θ_S`.
    Share,
}

/// Claimed Fresh Work outputs to check in Stage A (§6.2).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ClaimedWork {
    /// Claimed `outputRoot`.
    pub output_root: Digest,
    /// Claimed `WorkID`.
    pub work_id: Digest,
    /// Claimed `θ_S`.
    pub share_ticket: Digest,
    /// Claimed `(block_id, θ_B)`, present for a header seal.
    pub seal_fields: Option<(Digest, Digest)>,
}

impl ClaimedWork {
    /// Extracts claimed outputs from a `BlockHeader`.
    pub fn from_header(h: &BlockHeader) -> Self {
        Self {
            output_root: h.output_root,
            work_id: h.work_id,
            share_ticket: h.share_ticket,
            seal_fields: Some((h.block_id, h.seal_ticket)),
        }
    }

    /// Extracts claimed outputs from a `ShareProof`.
    pub fn from_share(s: &ShareProof) -> Self {
        Self {
            output_root: s.output_root,
            work_id: s.work_id,
            share_ticket: s.share_ticket,
            seal_fields: None,
        }
    }
}

/// Stage A Fresh Work verification error.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum WorkError {
    /// A context integer does not fit the core field width (names the field).
    ContextFieldOverflow(&'static str),
    /// Recomputed `outputRoot` differs from the claim.
    OutputRootMismatch,
    /// Recomputed `WorkID` differs from the claim.
    WorkIdMismatch,
    /// Recomputed `BlockID` differs from the claim (or a seal claim is missing).
    BlockIdMismatch,
    /// Recomputed `θ_S` differs from the claim.
    ShareTicketMismatch,
    /// Recomputed `θ_B` differs from the claim.
    SealTicketMismatch,
    /// The lottery value is not below its target.
    TargetNotMet,
    /// A header, share or job signature does not verify (names the object).
    Signature(&'static str, SignatureError),
    /// The verification task failed to run (panicked or was cancelled).
    Internal(String),
}

impl fmt::Display for WorkError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            WorkError::ContextFieldOverflow(field) => {
                write!(f, "context field {field} overflowed core integer type")
            }
            WorkError::OutputRootMismatch => write!(f, "output_root mismatch"),
            WorkError::WorkIdMismatch => write!(f, "work_id mismatch"),
            WorkError::BlockIdMismatch => write!(f, "block_id mismatch"),
            WorkError::ShareTicketMismatch => write!(f, "share_ticket mismatch"),
            WorkError::SealTicketMismatch => write!(f, "seal_ticket mismatch"),
            WorkError::TargetNotMet => write!(f, "lottery ticket did not meet target"),
            WorkError::Signature(what, err) => write!(f, "{what} signature: {err}"),
            WorkError::Internal(msg) => write!(f, "verification task failed: {msg}"),
        }
    }
}

impl std::error::Error for WorkError {}

/// Recomputes the 512x512 INT8 tile product for `ctx` and verifies the claimed outputs
/// and the lottery target (§6.2).
pub fn verify_fresh_work(
    ctx: &FwContext,
    claimed: &ClaimedWork,
    target: Target,
    lottery: Lottery,
) -> Result<(), WorkError> {
    let ids = evaluate_fresh_work(ctx)?;
    if ids.output_root != claimed.output_root {
        return Err(WorkError::OutputRootMismatch);
    }
    if ids.work_id != claimed.work_id {
        return Err(WorkError::WorkIdMismatch);
    }
    if ids.share_ticket != claimed.share_ticket {
        return Err(WorkError::ShareTicketMismatch);
    }

    let ticket = match lottery {
        Lottery::Seal => {
            let Some((claimed_block_id, claimed_seal_ticket)) = claimed.seal_fields else {
                return Err(WorkError::BlockIdMismatch);
            };
            if ids.block_id != claimed_block_id {
                return Err(WorkError::BlockIdMismatch);
            }
            if ids.seal_ticket != claimed_seal_ticket {
                return Err(WorkError::SealTicketMismatch);
            }
            ids.seal_ticket
        }
        Lottery::Share => ids.share_ticket,
    };
    if top128(&ticket) >= target.0 {
        return Err(WorkError::TargetNotMet);
    }
    Ok(())
}
