cat << 'EOF' > node/src/engine.rs
//! ConsensusEngine: multi-threaded Fresh Work miner (`node::engine`, §8.5).

use std::sync::Arc;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::time::{Duration, Instant};

/// How long a miner waits after a seal for the template built on its block.
const SEAL_HANDOFF: Duration = Duration::from_secs(2);

use chain::core_adapter::{fw_context_to_core, hash_to_digest};
use chain::{Template, top128};
use tokio::sync::{mpsc, watch};
use tracing::error;
use work::{DEFAULT_FREIVALDS_ROUNDS, FreshWorkIds, verify_freivalds_rounds};

use crate::chain_actor::ChainCmd;

/// Mining statistics and runtime controls of the `ConsensusEngine` (§8.5).
pub struct ConsensusEngine {
    threads: usize,
    enabled: AtomicBool,
    /// Closed while `--mine-when-synced` waits for peers and sync; miners run only while
    /// both `enabled` and this hold.
    sync_gate: AtomicBool,
    shutdown: AtomicBool,
    attempts: AtomicU64,
    shares_found: AtomicU64,
    seals_found: AtomicU64,
    rate_bits: AtomicU64, // f64::to_bits of the EWMA attempts/sec
}

impl ConsensusEngine {
    /// Spawns `threads` OS miner threads and the EWMA rate task (§8.5). With
    /// `gated`, the miners wait until [`Self::set_sync_gate`] opens the sync gate.
    pub fn spawn(
        threads: usize,
        initially_enabled: bool,
        gated: bool,
        templates: watch::Receiver<Option<Arc<Template>>>,
        chain_tx: mpsc::Sender<ChainCmd>,
    ) -> std::io::Result<Arc<Self>> {
        let engine = Arc::new(Self {
            threads,
            enabled: AtomicBool::new(initially_enabled && threads > 0),
            sync_gate: AtomicBool::new(!gated),
            shutdown: AtomicBool::new(false),
            attempts: AtomicU64::new(0),
            shares_found: AtomicU64::new(0),
            seals_found: AtomicU64::new(0),
            rate_bits: AtomicU64::new(0.0f64.to_bits()),
        });

        for i in 0..threads {
            let eng = engine.clone();
            let tpl_rx = templates.clone();
            let tx = chain_tx.clone();
            std::thread::Builder::new()
                .name(format!("plau-miner-{i}"))
                .spawn(move || miner_thread_loop(i, threads, &eng, &tpl_rx, &tx))?;
        }

        // EWMA of attempts per second with a 10 s time constant.
        let eng_rate = engine.clone();
        tokio::spawn(async move {
            let mut prev_attempts = eng_rate.attempts.load(Ordering::Relaxed);
            let mut ewma = 0.0f64;
            let alpha = 1.0 - (-1.0f64 / 10.0).exp();
            let mut interval = tokio::time::interval(Duration::from_secs(1));
            loop {
                interval.tick().await;
                if eng_rate.shutdown.load(Ordering::Relaxed) {
                    break;
                }
                let cur = eng_rate.attempts.load(Ordering::Relaxed);
                let delta = cur.saturating_sub(prev_attempts) as f64;
                prev_attempts = cur;
                ewma = if ewma == 0.0 {
                    delta
                } else {
                    alpha * delta + (1.0 - alpha) * ewma
                };
                eng_rate.rate_bits.store(ewma.to_bits(), Ordering::Relaxed);
            }
        });

        Ok(engine)
    }

    /// Enables or pauses mining on every worker thread (§8.5).
    pub fn set_enabled(&self, enabled: bool) {
        if self.threads > 0 {
            self.enabled.store(enabled, Ordering::Relaxed);
        }
    }

    /// Whether mining is enabled (it may still wait for the sync gate).
    pub fn is_enabled(&self) -> bool {
        self.enabled.load(Ordering::Relaxed)
    }

    /// Opens or closes the sync gate (`--mine-when-synced`).
    pub fn set_sync_gate(&self, open: bool) {
        self.sync_gate.store(open, Ordering::Relaxed);
    }

    /// Whether the sync gate lets the miners run.
    pub fn sync_gate_open(&self) -> bool {
        self.sync_gate.load(Ordering::Relaxed)
    }

    /// Number of miner threads.
    pub fn threads(&self) -> usize {
        self.threads
    }

    /// EWMA of attempts per second.
    pub fn attempts_per_sec(&self) -> f64 {
        f64::from_bits(self.rate_bits.load(Ordering::Relaxed))
    }

    /// Total attempts evaluated.
    pub fn attempts(&self) -> u64 {
        self.attempts.load(Ordering::Relaxed)
    }

    /// Shares found.
    pub fn shares_found(&self) -> u64 {
        self.shares_found.load(Ordering::Relaxed)
    }

    /// Seals found.
    pub fn seals_found(&self) -> u64 {
        self.seals_found.load(Ordering::Relaxed)
    }

    /// Stops every miner thread for good.
    pub fn shutdown(&self) {
        self.shutdown.store(true, Ordering::Relaxed);
        self.enabled.store(false, Ordering::Relaxed);
    }
}

fn miner_thread_loop(
    thread_idx: usize,
    num_threads: usize,
    engine: &ConsensusEngine,
    templates: &watch::Receiver<Option<Arc<Template>>>,
    chain_tx: &mpsc::Sender<ChainCmd>,
) {
    let stride = num_threads.max(1) as u64;
    let mut generation = None;
    let mut nonce = thread_idx as u64;
    let mut sealed_at: Option<Instant> = None;
    while !engine.shutdown.load(Ordering::Relaxed) {
        if !engine.enabled.load(Ordering::Relaxed) || !engine.sync_gate.load(Ordering::Relaxed) {
            std::thread::sleep(Duration::from_millis(100));
            continue;
        }
        let Some(tpl) = templates.borrow().clone() else {
            std::thread::sleep(Duration::from_millis(200));
            continue;
        };
        if generation != Some(tpl.generation) {
            generation = Some(tpl.generation);
            nonce = thread_idx as u64;
            sealed_at = None;
        }
        // After a seal, give the ChainState actor time to publish the template built on
        // top of it; if the block did not become the tip, keep mining this template.
        if sealed_at.is_some_and(|t| t.elapsed() < SEAL_HANDOFF) {
            std::thread::sleep(Duration::from_millis(50));
            continue;
        }

        let Ok(ctx) = fw_context_to_core(&tpl.context_with_nonce(nonce)) else {
            error!("Template context does not fit the core types");
            std::thread::sleep(Duration::from_millis(200));
            continue;
        };
        let inst = ctx.instance();
        let z = inst.x.product(&inst.y);
        let ids = FreshWorkIds::derive(&ctx, &z);
        engine.attempts.fetch_add(1, Ordering::Relaxed);

        let seal = top128(&hash_to_digest(&ids.seal_ticket)) < tpl.seal_target.0;
        let share = top128(&hash_to_digest(&ids.share_ticket)) < tpl.share_target.0;
        if (seal || share)
            && !verify_freivalds_rounds(&inst.x, &inst.y, &z, DEFAULT_FREIVALDS_ROUNDS)
        {
            error!("Freivalds self-check failed: engine or hardware fault");
        } else if seal {
            // The header share rule (§6.7) covers a sealing attempt; no ShareProof.
            engine.seals_found.fetch_add(1, Ordering::Relaxed);
            match tpl.seal(nonce, &ids) {
                Ok(block) => {
                    let _ = chain_tx.blocking_send(ChainCmd::SubmitLocalBlock(Box::new(block)));
                }
                Err(e) => error!(error = %e, "Could not sign a sealed block"),
            }
            sealed_at = Some(Instant::now());
        } else if share {
            engine.shares_found.fetch_add(1, Ordering::Relaxed);
            match tpl.share(nonce, &ids) {
                Ok(proof) => {
                    let _ = chain_tx.blocking_send(ChainCmd::SubmitLocalShare(Box::new(proof)));
                }
                Err(e) => error!(error = %e, "Could not sign a share proof"),
            }
        }
        nonce = nonce.wrapping_add(stride);
    }
}
EOF

cat << 'EOF' > node/src/keystore.rs
//! Persistent ML-DSA-87 miner key (`node::keystore`).
//!
//! The key file holds only the 32-byte FIPS 204 seed behind a versioned magic:
//! `PLAU/MLDSA87/v1\n || seed`. The full key pair is re-derived from the seed on load.

use std::io::Write;
use std::path::{Path, PathBuf};

use chain::OwnerKeypair;
use chain::keys::SEED_LEN;

use crate::NodeError;

/// Default key file name inside `--data-dir`.
pub const KEY_FILE_NAME: &str = "miner_key.bin";

/// Lock file a running node holds in its data directory.
pub const LOCK_FILE_NAME: &str = "LOCK";

/// Versioned header of the key file.
const KEY_FILE_MAGIC: &[u8; 16] = b"PLAU/MLDSA87/v1\n";

/// Total key file length: magic plus seed.
const KEY_FILE_LEN: usize = KEY_FILE_MAGIC.len() + SEED_LEN;

/// The key file to use: `key_file` if given, else `miner_key.bin` in `data_dir`.
pub fn key_path(data_dir: &Path, key_file: Option<&Path>) -> PathBuf {
    key_file.map_or_else(|| data_dir.join(KEY_FILE_NAME), Path::to_path_buf)
}

/// Loads the miner key from `path`, or generates one and saves it there if the file
/// does not exist. Returns the key pair and whether it was created.
///
/// An existing key file is never overwritten: a file that is not a valid key file,
/// or a symlink whose target is missing, is an error. If another process creates the
/// file at the same moment, its key is loaded instead.
pub fn load_or_create(path: &Path) -> Result<(OwnerKeypair, bool), NodeError> {
    match std::fs::read(path) {
        Ok(bytes) => Ok((parse_key_file(path, &bytes)?, false)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            if std::fs::symlink_metadata(path).is_ok() {
                return Err(format!(
                    "miner key {} is a symlink to a missing file; refusing to replace it",
                    path.display()
                )
                .into());
            }
            let keypair = OwnerKeypair::generate()?;
            match publish_key_file(path, keypair.seed()) {
                Ok(()) => Ok((keypair, true)),
                Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
                    Ok((parse_key_file(path, &std::fs::read(path)?)?, false))
                }
                Err(e) => Err(format!("cannot write miner key {}: {e}", path.display()).into()),
            }
        }
        Err(e) => Err(format!("cannot read miner key {}: {e}", path.display()).into()),
    }
}

fn parse_key_file(path: &Path, bytes: &[u8]) -> Result<OwnerKeypair, NodeError> {
    if bytes.len() != KEY_FILE_LEN || !bytes.starts_with(KEY_FILE_MAGIC) {
        return Err(format!(
            "{} is not a Plauthium ML-DSA-87 key file ({} bytes); move it away to generate a new key",
            path.display(),
            bytes.len()
        )
        .into());
    }
    let seed: [u8; SEED_LEN] = bytes[KEY_FILE_MAGIC.len()..]
        .try_into()
        .map_err(|_| "key file seed has the wrong length")?;
    Ok(OwnerKeypair::from_seed(&seed))
}

/// Writes the key file without ever replacing an existing one. The seed goes to a
/// uniquely named temporary file (created exclusively, owner-only on Unix), which is
/// then hard-linked to `path`. Linking fails with `AlreadyExists` if `path` exists, so
/// a crash never leaves a truncated key and a concurrent start never overwrites one.
fn publish_key_file(path: &Path, seed: &[u8; SEED_LEN]) -> std::io::Result<()> {
    let parent = path.parent().filter(|p| !p.as_os_str().is_empty());
    if let Some(parent) = parent {
        std::fs::create_dir_all(parent)?;
    }
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let mut tmp_name = path.as_os_str().to_owned();
    tmp_name.push(format!(".{}.{nanos}.tmp", std::process::id()));
    let tmp_path = Path::new(&tmp_name);

    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let result = (|| {
        let mut file = options.open(tmp_path)?;
        file.write_all(KEY_FILE_MAGIC)?;
        file.write_all(seed)?;
        file.sync_all()?;
        drop(file);
        std::fs::hard_link(tmp_path, path)
    })();
    let _ = std::fs::remove_file(tmp_path);
    result?;
    // Make the new directory entry durable (best effort; not every platform allows it).
    if let Some(parent) = parent
        && let Ok(dir) = std::fs::File::open(parent)
    {
        let _ = dir.sync_all();
    }
    Ok(())
}

/// Locks `data_dir` (creating it if needed) for as long as the returned file stays
/// open: two nodes on one data directory would corrupt each other's `blocks.log`.
pub fn lock_data_dir(data_dir: &Path) -> Result<std::fs::File, NodeError> {
    std::fs::create_dir_all(data_dir)?;
    let path = data_dir.join(LOCK_FILE_NAME);
    let file = std::fs::OpenOptions::new()
        .create(true)
        .truncate(false)
        .write(true)
        .open(&path)?;
    match file.try_lock() {
        Ok(()) => Ok(file),
        Err(std::fs::TryLockError::WouldBlock) => Err(format!(
            "data directory {} is in use by another plauthium-node",
            data_dir.display()
        )
        .into()),
        Err(std::fs::TryLockError::Error(e)) => {
            Err(format!("cannot lock {}: {e}", path.display()).into())
        }
    }
}

/// `--reset`: deletes everything in `data_dir` except the key file at `key_path` (so
/// the node keeps its identity across resets) and the lock file.
///
/// Directories on the way to the key file are emptied instead of deleted. Symlinks
/// are never followed: one leading to the key file or to a directory holding it is
/// kept, any other is removed as a link.
pub fn reset_data_dir(data_dir: &Path, key_path: &Path) -> Result<(), NodeError> {
    let keep: Vec<PathBuf> = [key_path.to_path_buf(), data_dir.join(LOCK_FILE_NAME)]
        .iter()
        .filter_map(|p| p.canonicalize().ok())
        .collect();
    clear_dir(data_dir, &keep)?;
    Ok(())
}

fn clear_dir(dir: &Path, keep: &[PathBuf]) -> std::io::Result<()> {
    for entry in std::fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?; // does not follow symlinks
        if let Ok(canonical) = path.canonicalize()
            && keep.iter().any(|k| k.starts_with(&canonical))
        {
            // A kept file itself, or a directory or symlink on the way to one.
            if file_type.is_dir() && !keep.contains(&canonical) {
                clear_dir(&path, keep)?;
            }
            continue;
        }
        if file_type.is_dir() {
            std::fs::remove_dir_all(&path)?;
        } else {
            std::fs::remove_file(&path)?;
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp_dir(label: &str) -> std::path::PathBuf {
        let dir = std::env::temp_dir().join(format!(
            "plau-keystore-{label}-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn key_is_created_once_then_loaded_and_survives_reset() {
        let dir = temp_dir("persist");
        let key_path = dir.join(KEY_FILE_NAME);

        let (created, was_new) = load_or_create(&key_path).unwrap();
        assert!(was_new);
        let bytes = std::fs::read(&key_path).unwrap();
        assert_eq!(bytes.len(), KEY_FILE_LEN);
        assert!(bytes.starts_with(KEY_FILE_MAGIC));
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = std::fs::metadata(&key_path).unwrap().permissions().mode();
            assert_eq!(mode & 0o777, 0o600, "the key file is private");
        }

        let (loaded, was_new) = load_or_create(&key_path).unwrap();
        assert!(!was_new);
        assert_eq!(loaded.key_id(), created.key_id());
        assert_eq!(loaded.public_key(), created.public_key());

        // --reset wipes the chain data but keeps the key and the lock file.
        std::fs::write(dir.join("blocks.log"), b"chain data").unwrap();
        std::fs::create_dir_all(dir.join("sub")).unwrap();
        let lock = lock_data_dir(&dir).unwrap();
        reset_data_dir(&dir, &key_path).unwrap();
        assert!(!dir.join("blocks.log").exists());
        assert!(!dir.join("sub").exists());
        assert!(dir.join(LOCK_FILE_NAME).exists());
        // While it is locked, a second node cannot use the directory.
        assert!(lock_data_dir(&dir).is_err());
        drop(lock);
        drop(lock_data_dir(&dir).unwrap());
        let (after_reset, was_new) = load_or_create(&key_path).unwrap();
        assert!(!was_new);
        assert_eq!(after_reset.key_id(), created.key_id());

        // Two fresh key files hold two different identities.
        let other_path = dir.join("other.bin");
        let (other, _) = load_or_create(&other_path).unwrap();
        assert_ne!(other.key_id(), created.key_id());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn reset_keeps_a_nested_key_and_never_follows_symlinks() {
        let dir = temp_dir("nested");
        let key_path = dir.join("keys").join("miner.bin");
        let (created, _) = load_or_create(&key_path).unwrap();
        std::fs::write(dir.join("keys").join("other"), b"x").unwrap();
        std::fs::write(dir.join("blocks.log"), b"chain data").unwrap();

        // Outside data: a directory reached through a symlink must survive the reset.
        let outside = temp_dir("nested-outside");
        std::fs::write(outside.join("precious"), b"keep me").unwrap();
        #[cfg(unix)]
        std::os::unix::fs::symlink(&outside, dir.join("link")).unwrap();

        reset_data_dir(&dir, &key_path).unwrap();
        assert!(key_path.exists(), "the nested key file survives");
        assert!(!dir.join("keys").join("other").exists());
        assert!(!dir.join("blocks.log").exists());
        assert!(
            outside.join("precious").exists(),
            "symlinks are not followed"
        );
        #[cfg(unix)]
        assert!(std::fs::symlink_metadata(dir.join("link")).is_err());
        let (loaded, was_new) = load_or_create(&key_path).unwrap();
        assert!(!was_new);
        assert_eq!(loaded.key_id(), created.key_id());
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::remove_dir_all(&outside);
    }

    #[test]
    fn an_existing_key_is_never_overwritten() {
        let dir = temp_dir("exclusive");
        let key_path = dir.join(KEY_FILE_NAME);
        let (first, _) = load_or_create(&key_path).unwrap();
        let before = std::fs::read(&key_path).unwrap();

        // Publishing over an existing key fails instead of replacing it...
        let err = publish_key_file(&key_path, &[9; SEED_LEN]).unwrap_err();
        assert_eq!(err.kind(), std::io::ErrorKind::AlreadyExists);
        assert_eq!(std::fs::read(&key_path).unwrap(), before);
        // ...and leaves no temporary file behind.
        let leftovers = std::fs::read_dir(&dir).unwrap().count();
        assert_eq!(leftovers, 1);
        assert_eq!(
            load_or_create(&key_path).unwrap().0.key_id(),
            first.key_id()
        );

        // A symlink to a missing file is refused rather than replaced.
        #[cfg(unix)]
        {
            let link = dir.join("dangling.bin");
            std::os::unix::fs::symlink(dir.join("missing"), &link).unwrap();
            assert!(load_or_create(&link).is_err());
            assert!(
                std::fs::symlink_metadata(&link)
                    .unwrap()
                    .file_type()
                    .is_symlink()
            );
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_damaged_key_file_is_rejected_and_kept() {
        let dir = temp_dir("damaged");
        let key_path = dir.join(KEY_FILE_NAME);
        std::fs::write(&key_path, b"not a key").unwrap();
        assert!(load_or_create(&key_path).is_err());
        assert_eq!(std::fs::read(&key_path).unwrap(), b"not a key");

        let mut wrong_magic = vec![0u8; KEY_FILE_LEN];
        wrong_magic[..4].copy_from_slice(b"PLAU");
        std::fs::write(&key_path, &wrong_magic).unwrap();
        assert!(load_or_create(&key_path).is_err());
        let _ = std::fs::remove_dir_all(&dir);
    }
}
EOF

cat << 'EOF' > node/src/lib.rs
//! Plauthium Testnet node library: actors, P2P networking, miner, RPC and explorer.
//!
//! The `plauthium-node` binary (`src/main.rs`) is a thin CLI over [`start_node`] and
//! [`run_genesis_cmd`]; integration tests start several nodes in one process through
//! the same entry points.

#![forbid(unsafe_code)]

pub mod chain_actor;
pub mod cli;
pub mod engine;
pub mod keystore;
pub mod mempool;
pub mod net;
pub mod rpc;
pub mod share_pool;
pub mod store;

use std::net::SocketAddr;
use std::sync::Arc;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use tokio::sync::{Semaphore, broadcast, mpsc, watch};
use tokio::task::JoinHandle;
use tracing::{info, warn};
use wire::{DifficultyMode, Digest, GenesisConfig, Target};

use crate::chain_actor::{ChainActor, ChainCmd, ChainEvent, StatusSnapshot};
use crate::cli::{DifficultyArg, GenesisArgs, KeyArgs, RunArgs};
use crate::engine::ConsensusEngine;
use crate::mempool::{MempoolActor, MempoolCmd, MempoolEvent, MempoolView};
use crate::net::PeerManager;
use crate::rpc::spawn_rpc_server;
use crate::store::BlockStore;

/// Embedded default genesis JSON (§3.4).
pub const DEFAULT_GENESIS_JSON: &str = include_str!("../genesis.testnet.json");

/// Boxed error type of the node entry points.
pub type NodeError = Box<dyn std::error::Error + Send + Sync>;

/// Handle to a running in-process node (used by `main` and the integration tests).
pub struct NodeHandle {
    /// Bound P2P listen address.
    pub p2p_addr: SocketAddr,
    /// Bound RPC / explorer address.
    pub rpc_addr: SocketAddr,
    /// Key id of this node's ML-DSA-87 miner key.
    pub miner_key_id: Digest,
    /// Command channel of the ChainState actor.
    pub chain_tx: mpsc::Sender<ChainCmd>,
    /// Command channel of the mempool actor.
    pub mempool_tx: mpsc::Sender<MempoolCmd>,
    /// Latest chain status.
    pub status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    /// The Fresh Work miner.
    pub engine: Arc<ConsensusEngine>,
    /// The P2P layer.
    pub peer_manager: Arc<PeerManager>,
    shutdown_tx: watch::Sender<bool>,
    tasks: Vec<JoinHandle<()>>,
    /// Held until the node is dropped: no second node can use the data directory.
    _data_dir_lock: std::fs::File,
}

impl NodeHandle {
    /// Signals graceful shutdown of every task, connection and miner thread.
    pub fn shutdown(&self) {
        self.engine.shutdown();
        let _ = self.shutdown_tx.send(true);
    }

    /// Signals shutdown and waits until the ChainState and mempool actors have exited
    /// (the ChainState actor flushes `blocks.log` on exit).
    pub async fn stop(self) {
        self.shutdown();
        for task in self.tasks {
            let _ = task.await;
        }
    }
}

fn unix_now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

/// Builds the genesis configuration for `plauthium-node genesis` with
/// `genesis_time_bucket = now`.
pub fn genesis_from_args(args: &GenesisArgs) -> Result<GenesisConfig, NodeError> {
    let mut cfg = GenesisConfig::default_testnet(0);
    cfg.genesis_time_bucket = unix_now_secs() / cfg.time_bucket_secs;
    cfg.name = args.name.clone();
    cfg.initial_seal_target = Target(u128::MAX / u128::from(args.seal_attempts.max(1)));
    cfg.share_ratio = args.share_ratio;
    cfg.difficulty = match args.difficulty {
        DifficultyArg::Fixed => DifficultyMode::Fixed,
        DifficultyArg::Windowed => DifficultyMode::Windowed {
            window: args.retarget_window,
        },
    };
    cfg.target_block_secs = args.target_block_secs;
    cfg.blocks_per_epoch = args.blocks_per_epoch;
    cfg.settle_delay = args.settle_delay;
    chain::validate_genesis(&cfg)?;
    Ok(cfg)
}

/// `plauthium-node genesis`: writes a validated genesis JSON file.
pub fn run_genesis_cmd(args: GenesisArgs) -> Result<(), NodeError> {
    let cfg = genesis_from_args(&args)?;
    let genesis_id = chain::compute_genesis_id(&cfg)?;
    if let Some(parent) = args.out.parent()
        && !parent.as_os_str().is_empty()
    {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(&args.out, serde_json::to_string_pretty(&cfg)?)?;
    info!(path = %args.out.display(), %genesis_id, "Wrote genesis configuration");
    Ok(())
}

/// `plauthium-node key`: loads the miner key, creating it first if it does not exist,
/// and prints where it is and the identity it gives the node.
pub fn run_key_cmd(args: KeyArgs) -> Result<(), NodeError> {
    let key_path = keystore::key_path(&args.data_dir, args.key_file.as_deref());
    let (key, created) = keystore::load_or_create(&key_path)?;
    println!("key_file: {}", key_path.display());
    println!("status: {}", if created { "created" } else { "loaded" });
    println!("key_id: {}", key.key_id().to_hex());
    println!("owner_id: {}", key.owner_id());
    Ok(())
}

/// Loads the genesis file named by `--genesis`, or the embedded default.
pub fn load_genesis(args: &RunArgs) -> Result<GenesisConfig, NodeError> {
    let genesis: GenesisConfig = match &args.genesis {
        Some(path) => serde_json::from_str(&std::fs::read_to_string(path)?)?,
        None => serde_json::from_str(DEFAULT_GENESIS_JSON)?,
    };
    chain::validate_genesis(&genesis)?;
    Ok(genesis)
}

/// Grace period before warning that no peer is connected, and the interval between
/// such warnings.
const NO_PEER_GRACE: Duration = Duration::from_secs(30);
const NO_PEER_WARNING_INTERVAL: Duration = Duration::from_secs(60);
/// With `--mine-when-synced`, mining also starts once the tip has not moved for this
/// long while a peer is connected: a peer may claim a height it cannot deliver.
const SYNC_STALL: Duration = Duration::from_secs(60);

/// Watches the connection to the network. A node with static peers warns while none is
/// connected. With `--mine-when-synced` (`gated`) it also opens the mining gate once a
/// peer is connected and the node has caught up with the best height peers report, or
/// syncing has stalled; the gate then stays open until no peer is left.
fn spawn_peer_watch(
    engine: Arc<ConsensusEngine>,
    peers: Arc<PeerManager>,
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    mut shutdown: watch::Receiver<bool>,
    gated: bool,
    has_static_peers: bool,
) {
    if !gated && !has_static_peers {
        return;
    }
    tokio::spawn(async move {
        let mut alone_since = Instant::now();
        let mut last_warning: Option<Instant> = None;
        let mut progress = (status_rx.borrow().tip.height, Instant::now());
        loop {
            let tip = status_rx.borrow().tip.height;
            if tip != progress.0 {
                progress = (tip, Instant::now());
            }
            let connected = peers.peer_count() > 0;
            if connected {
                alone_since = Instant::now();
            } else {
                // Only time spent connected without progress counts as a stalled sync.
                progress = (tip, Instant::now());
                if has_static_peers
                    && alone_since.elapsed() >= NO_PEER_GRACE
                    && last_warning.is_none_or(|t| t.elapsed() >= NO_PEER_WARNING_INTERVAL)
                {
                    warn!(
                        mining_paused = gated,
                        "No peer connected; check the --peer addresses and the network"
                    );
                    last_warning = Some(Instant::now());
                }
            }
            if gated {
                let caught_up = peers.best_peer_height().is_some_and(|best| tip >= best);
                let stalled = progress.1.elapsed() >= SYNC_STALL;
                let open = connected && (engine.sync_gate_open() || caught_up || stalled);
                if open != engine.sync_gate_open() {
                    engine.set_sync_gate(open);
                    if open {
                        info!(height = tip, "Connected and caught up; mining");
                    } else {
                        info!("No peer connected; mining paused until the node is caught up again");
                    }
                }
            }
            tokio::select! {
                () = tokio::time::sleep(Duration::from_secs(1)) => {}
                res = shutdown.changed() => {
                    if res.is_err() || *shutdown.borrow() {
                        break;
                    }
                }
            }
        }
    });
}

/// Starts all actors, P2P networking, the ConsensusEngine and the Axum RPC for one node.
pub async fn start_node(args: RunArgs) -> Result<NodeHandle, NodeError> {
    let profile_check = chain::testnet_ozaki_profile().validate();
    profile_check.map_err(|e| format!("TESTNET_PROFILE validation failed: {e}"))?;
    let genesis = load_genesis(&args)?;

    let key_path = keystore::key_path(&args.data_dir, args.key_file.as_deref());
    let data_dir_lock = keystore::lock_data_dir(&args.data_dir)?;
    if args.reset {
        keystore::reset_data_dir(&args.data_dir, &key_path)?;
    }
    let (miner, created) = keystore::load_or_create(&key_path)?;
    let miner = Arc::new(miner);
    info!(
        key_id = %miner.key_id().short_hex(16),
        owner_id = miner.owner_id(),
        path = %key_path.display(),
        "{} ML-DSA-87 miner key",
        if created { "Generated a new" } else { "Loaded the" }
    );
    let (log_writer, disk_blocks) = BlockStore::open(&args.data_dir.join("blocks.log"))?;

    let (chain_tx, chain_rx) = mpsc::channel::<ChainCmd>(1_024);
    let (mempool_tx, mempool_rx) = mpsc::channel::<MempoolCmd>(1_024);
    let (chain_event_tx, _) = broadcast::channel::<ChainEvent>(1_024);
    let (mempool_event_tx, _) = broadcast::channel::<MempoolEvent>(1_024);
    let (mempool_view_tx, mempool_view_rx) = watch::channel(Arc::new(MempoolView::default()));
    let (template_tx, template_rx) = watch::channel(None);
    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    let verify_threads = args.verify_threads.unwrap_or_else(|| {
        std::thread::available_parallelism().map_or(2, |n| (n.get() / 2).max(1))
    });
    let verify_semaphore = Arc::new(Semaphore::new(verify_threads.max(1)));

    let (mut chain_actor, status_rx) = ChainActor::new(
        genesis.clone(),
        miner.clone(),
        log_writer,
        chain_tx.clone(),
        chain_rx,
        chain_event_tx.clone(),
        template_tx,
        mempool_view_rx.clone(),
        verify_semaphore,
    )?;
    // Persisted blocks are replayed before any peer connects (Origin::Disk, §8.7).
    chain_actor.replay_disk_blocks(disk_blocks);

    let mining_threads = if args.no_mine { 0 } else { args.mining_threads };
    let gated = args.mine_when_synced && mining_threads > 0;
    let engine = ConsensusEngine::spawn(
        mining_threads,
        mining_threads > 0,
        gated,
        template_rx,
        chain_tx.clone(),
    )?;

    let mempool_actor = MempoolActor::new(
        mempool_rx,
        chain_tx.clone(),
        chain_event_tx.subscribe(),
        mempool_event_tx.clone(),
        mempool_view_tx,
        status_rx.clone(),
    );
    let mut tasks = vec![tokio::spawn(mempool_actor.run(shutdown_rx.clone()))];
    tasks.push(tokio::spawn(chain_actor.run(shutdown_rx.clone())));

    let peer_manager = PeerManager::start(
        args.p2p_listen,
        args.peers.clone(),
        genesis.chain_id,
        chain_tx.clone(),
        mempool_tx.clone(),
        chain_event_tx.subscribe(),
        mempool_event_tx.subscribe(),
        status_rx.clone(),
        shutdown_rx.clone(),
    )
    .await?;
    let p2p_addr = peer_manager.local_addr();
    spawn_peer_watch(
        engine.clone(),
        peer_manager.clone(),
        status_rx.clone(),
        shutdown_rx.clone(),
        gated,
        !args.peers.is_empty(),
    );

    let rpc_addr = spawn_rpc_server(
        args.rpc_listen,
        status_rx.clone(),
        mempool_view_rx,
        chain_tx.clone(),
        mempool_tx.clone(),
        engine.clone(),
        peer_manager.clone(),
        miner.clone(),
        shutdown_rx,
    )
    .await?;

    Ok(NodeHandle {
        p2p_addr,
        rpc_addr,
        miner_key_id: miner.key_id(),
        chain_tx,
        mempool_tx,
        status_rx,
        engine,
        peer_manager,
        shutdown_tx,
        tasks,
        _data_dir_lock: data_dir_lock,
    })
}
EOF

cat << 'EOF' > node/src/main.rs
//! `plauthium-node`: the Plauthium testnet daemon.

#![forbid(unsafe_code)]

use clap::Parser;
use node::NodeError;
use node::cli::{Cli, Command};
use tracing::info;

#[tokio::main]
async fn main() -> Result<(), NodeError> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    match Cli::parse().command {
        Command::Genesis(args) => node::run_genesis_cmd(args)?,
        Command::Key(args) => node::run_key_cmd(args)?,
        Command::Run(args) => {
            let handle = node::start_node(args).await?;
            info!(
                p2p = %handle.p2p_addr,
                rpc = %handle.rpc_addr,
                "plauthium-node started; press Ctrl-C to stop"
            );
            tokio::signal::ctrl_c().await?;
            info!("Ctrl-C received; shutting down gracefully");
            handle.stop().await;
            info!("Shutdown complete");
        }
    }
    Ok(())
}
EOF

cat << 'EOF' > node/src/mempool.rs
//! Mempool actor (`node::mempool`, §8.4).

use std::collections::{HashMap, HashSet, VecDeque};
use std::sync::Arc;

use chain::{JobValidationError, compute_job_ids, validate_job_stateless, verify_job_client};
use tokio::sync::{broadcast, mpsc, oneshot, watch};
use tracing::warn;
use wire::{Block, Digest, JobTransaction, MEMPOOL_CAPACITY};

use crate::chain_actor::{ChainCmd, ChainEvent, Origin, StatusSnapshot};

/// FIFO snapshot of pooled transactions, published to the ChainState actor for templates.
#[derive(Clone, Debug, Default)]
pub struct MempoolView {
    /// Oldest first, at most `4 * max_jobs_per_block` entries.
    pub txs: Vec<JobTransaction>,
    /// Total number of pooled transactions.
    pub size: usize,
}

/// Event broadcast by `MempoolActor` when a job is accepted.
#[derive(Clone, Debug)]
pub enum MempoolEvent {
    /// A new job entered the pool (relayed to peers except `origin`).
    Accepted {
        /// The job.
        tx: JobTransaction,
        /// Where it came from.
        origin: Origin,
    },
}

/// Successful insertion receipt returned to RPC and P2P callers.
#[derive(Clone, Debug)]
pub struct MempoolInsertOk {
    /// Transaction identifier.
    pub tx_id: Digest,
    /// Job identifier.
    pub job_id: u64,
    /// Escrow deposit `D`.
    pub deposit: u64,
    /// `D + f_queue`.
    pub total_charge: u64,
    /// Exact dot product the job will settle with.
    pub expected_result: i128,
}

/// Rejection reasons of `MempoolCmd::Insert`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MempoolReject {
    /// Same `tx_id` or `job_id` already pooled.
    Duplicate,
    /// The pool holds `MEMPOOL_CAPACITY` transactions (no fee-based eviction).
    Full,
    /// The transaction is invalid.
    Invalid {
        /// Stable error code for the RPC (§9.5).
        code: &'static str,
        /// Human-readable reason.
        message: String,
    },
}

/// Commands accepted by `MempoolActor`.
pub enum MempoolCmd {
    /// Validates and pools a job.
    Insert {
        /// The job.
        tx: JobTransaction,
        /// Where it came from.
        origin: Origin,
        /// Outcome.
        reply: oneshot::Sender<Result<MempoolInsertOk, MempoolReject>>,
    },
    /// Number of pooled transactions.
    Stats {
        /// Pool size.
        reply: oneshot::Sender<usize>,
    },
    /// The oldest `limit` pooled transactions.
    List {
        /// Maximum entries.
        limit: usize,
        /// Transactions, oldest first.
        reply: oneshot::Sender<Vec<JobTransaction>>,
    },
}

struct PooledEntry {
    tx_id: Digest,
    job_id: u64,
    tx: JobTransaction,
}

/// Asynchronous mempool actor (§8.4).
pub struct MempoolActor {
    cmd_rx: mpsc::Receiver<MempoolCmd>,
    chain_tx: mpsc::Sender<ChainCmd>,
    chain_events: broadcast::Receiver<ChainEvent>,
    event_tx: broadcast::Sender<MempoolEvent>,
    view_tx: watch::Sender<Arc<MempoolView>>,
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    fifo: VecDeque<PooledEntry>,
    by_tx_id: HashSet<Digest>,
    by_job_id: HashMap<u64, Digest>,
    // Jobs on the canonical chain that have not expired, by tx_id and by job_id, with
    // their expiry height (as the STF keeps them): a copy submitted again is a duplicate.
    included_tx: HashMap<Digest, u64>,
    included_jobs: HashMap<u64, u64>,
}

fn rejection_code(err: &JobValidationError) -> &'static str {
    match err {
        JobValidationError::ZeroFee(_) => "zero_fee",
        JobValidationError::AmountOverflow => "amount_overflow",
        JobValidationError::TooLarge(_) => "too_large",
        JobValidationError::InvalidPayload(_) => "invalid_payload",
    }
}

impl MempoolActor {
    /// Creates the actor; call [`MempoolActor::run`] to start it.
    pub fn new(
        cmd_rx: mpsc::Receiver<MempoolCmd>,
        chain_tx: mpsc::Sender<ChainCmd>,
        chain_events: broadcast::Receiver<ChainEvent>,
        event_tx: broadcast::Sender<MempoolEvent>,
        view_tx: watch::Sender<Arc<MempoolView>>,
        status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    ) -> Self {
        Self {
            cmd_rx,
            chain_tx,
            chain_events,
            event_tx,
            view_tx,
            status_rx,
            fifo: VecDeque::new(),
            by_tx_id: HashSet::new(),
            by_job_id: HashMap::new(),
            included_tx: HashMap::new(),
            included_jobs: HashMap::new(),
        }
    }

    /// Runs until `shutdown` turns true (or its sender is dropped).
    pub async fn run(mut self, mut shutdown: watch::Receiver<bool>) {
        loop {
            tokio::select! {
                res = shutdown.changed() => {
                    if res.is_err() || *shutdown.borrow() {
                        break;
                    }
                }
                Some(cmd) = self.cmd_rx.recv() => self.handle_cmd(cmd),
                ev = self.chain_events.recv() => match ev {
                    Ok(ChainEvent::TipChanged { tip, connected, disconnected }) => {
                        self.handle_tip_changed(tip.height, &connected, &disconnected);
                    }
                    Ok(_) => {}
                    Err(broadcast::error::RecvError::Lagged(skipped)) => {
                        warn!(skipped, "Mempool lagged behind chain events; asking ChainState");
                        self.recover_from_lag().await;
                    }
                    Err(broadcast::error::RecvError::Closed) => break,
                },
            }
        }
    }

    fn handle_cmd(&mut self, cmd: MempoolCmd) {
        match cmd {
            MempoolCmd::Insert { tx, origin, reply } => {
                let _ = reply.send(self.insert_tx(tx, origin));
            }
            MempoolCmd::Stats { reply } => {
                let _ = reply.send(self.fifo.len());
            }
            MempoolCmd::List { limit, reply } => {
                let _ = reply.send(self.fifo.iter().take(limit).map(|e| e.tx.clone()).collect());
            }
        }
    }

    fn next_height(&self) -> u64 {
        self.status_rx.borrow().tip.height + 1
    }

    fn insert_tx(
        &mut self,
        tx: JobTransaction,
        origin: Origin,
    ) -> Result<MempoolInsertOk, MempoolReject> {
        // Duplicates first: a re-signed or forged copy of a pooled job has the same
        // tx_id, and rejecting it costs one hash instead of a full validation.
        if let Ok((tx_id, job_id)) = compute_job_ids(&tx)
            && (self.by_tx_id.contains(&tx_id)
                || self.by_job_id.contains_key(&job_id)
                || self.included_tx.contains_key(&tx_id)
                || self.included_jobs.contains_key(&job_id))
        {
            return Err(MempoolReject::Duplicate);
        }
        let (tx_id, job_id, deposit, expected_result) =
            validate_job_stateless(&tx).map_err(|err| MempoolReject::Invalid {
                code: rejection_code(&err),
                message: err.to_string(),
            })?;
        let total_charge = tx
            .checked_total_charge()
            .ok_or_else(|| MempoolReject::Invalid {
                code: "amount_overflow",
                message: "total charge overflow".to_string(),
            })?;
        let next_height = self.next_height();
        if tx.expiry_height < next_height {
            return Err(MempoolReject::Invalid {
                code: "bad_request",
                message: format!(
                    "job expiry_height {} < next block height {next_height}",
                    tx.expiry_height
                ),
            });
        }
        if self.by_tx_id.contains(&tx_id) || self.by_job_id.contains_key(&job_id) {
            return Err(MempoolReject::Duplicate);
        }
        if self.fifo.len() >= MEMPOOL_CAPACITY {
            return Err(MempoolReject::Full);
        }
        // Last, so duplicates relayed by several peers never pay for a verification.
        let genesis_id = self.status_rx.borrow().genesis_id;
        verify_job_client(&tx, &genesis_id).map_err(|err| MempoolReject::Invalid {
            code: "bad_signature",
            message: format!("client signature: {err}"),
        })?;

        self.push(tx_id, job_id, tx.clone());
        self.publish_view();
        let _ = self.event_tx.send(MempoolEvent::Accepted { tx, origin });
        Ok(MempoolInsertOk {
            tx_id,
            job_id,
            deposit,
            total_charge,
            expected_result,
        })
    }

    fn push(&mut self, tx_id: Digest, job_id: u64, tx: JobTransaction) {
        self.by_tx_id.insert(tx_id);
        self.by_job_id.insert(job_id, tx_id);
        self.fifo.push_back(PooledEntry { tx_id, job_id, tx });
    }

    fn handle_tip_changed(
        &mut self,
        tip_height: u64,
        connected: &[Arc<Block>],
        disconnected: &[Arc<Block>],
    ) {
        let connected_txs: HashSet<Digest> = connected
            .iter()
            .flat_map(|blk| &blk.body.jobs)
            .filter_map(|tx| compute_job_ids(tx).ok().map(|(id, _)| id))
            .collect();
        let next_height = tip_height + 1;

        // Track the unexpired jobs of the canonical chain: the abandoned branch's leave,
        // the new branch's join.
        for tx in disconnected.iter().flat_map(|blk| &blk.body.jobs) {
            if let Ok((tx_id, job_id)) = compute_job_ids(tx) {
                self.included_tx.remove(&tx_id);
                self.included_jobs.remove(&job_id);
            }
        }
        for tx in connected.iter().flat_map(|blk| &blk.body.jobs) {
            if let Ok((tx_id, job_id)) = compute_job_ids(tx) {
                self.included_tx.insert(tx_id, tx.expiry_height);
                self.included_jobs.insert(job_id, tx.expiry_height);
            }
        }
        self.included_tx.retain(|_, expiry| *expiry >= next_height);
        self.included_jobs
            .retain(|_, expiry| *expiry >= next_height);

        // Remove txs included by the new branch, and txs that expired.
        self.remove_where(|e| connected_txs.contains(&e.tx_id) || e.tx.expiry_height < next_height);

        // Return the txs of the abandoned branch (already validated statelessly).
        for tx in disconnected.iter().flat_map(|blk| &blk.body.jobs) {
            if tx.expiry_height < next_height || self.fifo.len() >= MEMPOOL_CAPACITY {
                continue;
            }
            let Ok((tx_id, job_id)) = compute_job_ids(tx) else {
                continue;
            };
            if connected_txs.contains(&tx_id)
                || self.by_tx_id.contains(&tx_id)
                || self.by_job_id.contains_key(&job_id)
            {
                continue;
            }
            self.push(tx_id, job_id, tx.clone());
        }
        self.publish_view();
    }

    async fn recover_from_lag(&mut self) {
        let tx_ids: Vec<Digest> = self.by_tx_id.iter().copied().collect();
        let (reply_tx, reply_rx) = oneshot::channel();
        let request = ChainCmd::FilterIncluded {
            tx_ids,
            reply: reply_tx,
        };
        if self.chain_tx.send(request).await.is_err() {
            return;
        }
        let Ok(included) = reply_rx.await else {
            return;
        };
        let included: HashSet<Digest> = included.into_iter().collect();
        let next_height = self.next_height();
        self.remove_where(|e| included.contains(&e.tx_id) || e.tx.expiry_height < next_height);
        self.publish_view();
    }

    fn remove_where(&mut self, pred: impl Fn(&PooledEntry) -> bool) {
        let (by_tx_id, by_job_id) = (&mut self.by_tx_id, &mut self.by_job_id);
        self.fifo.retain(|entry| {
            let remove = pred(entry);
            if remove {
                by_tx_id.remove(&entry.tx_id);
                by_job_id.remove(&entry.job_id);
            }
            !remove
        });
    }

    fn publish_view(&self) {
        let max_jobs = usize::try_from(self.status_rx.borrow().max_jobs_per_block).unwrap_or(32);
        let cap = max_jobs.saturating_mul(4).max(32);
        let txs = self.fifo.iter().take(cap).map(|e| e.tx.clone()).collect();
        let _ = self.view_tx.send(Arc::new(MempoolView {
            txs,
            size: self.fifo.len(),
        }));
    }
}
EOF

cat << 'EOF' > node/src/net.rs
//! P2P network manager: length-delimited TCP framing, handshake, gossip relay, sync
//! driver and misbehaviour bans (`node::net`, §4, §8.6).

use std::collections::{HashMap, HashSet, VecDeque};
use std::net::SocketAddr;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex, MutexGuard};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use bytes::Bytes;
use futures::{SinkExt, StreamExt};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{broadcast, mpsc, oneshot, watch};
use tokio::time::Instant as TokioInstant;
use tokio_util::codec::{Framed, LengthDelimitedCodec};
use tracing::{debug, info, warn};
use wire::{
    Block, Digest, HANDSHAKE_TIMEOUT, MAX_FRAME_BYTES, MAX_REORG_DEPTH, MAX_SYNC_BLOCKS,
    MAX_SYNC_BYTES, SYNC_LOOKBACK, SYNC_TIMEOUT, ShareProof, WIRE_VERSION, WireMessage, codec,
};

use crate::chain_actor::{
    ChainCmd, ChainEvent, INVALID_BAN, ImportAck, Origin, PeerId, ShareAck, Source, StatusSnapshot,
};
use crate::mempool::{MempoolCmd, MempoolEvent, MempoolReject};

/// Ban for protocol violations (bad frames, unexpected messages), §4.8.
const PROTOCOL_BAN: Duration = Duration::from_secs(60);
/// Invalid jobs tolerated per connection before a ban.
const MAX_INVALID_JOBS: u32 = 10;
/// Gossiped shares a peer may send per minute that turn out useless (ignored, or a
/// duplicate under a new encoding). Past it, the peer's shares are dropped unread for
/// the rest of the minute. Honest peers relay a few shares per block.
const MAX_USELESS_SHARES_PER_MIN: u32 = 256;
/// Inbound connections accepted per source (an IP, or an IPv6 /64; loopback is exempt
/// for local testnets). Generous, for honest nodes sharing a NAT address; it bounds
/// sockets and per-connection budgets per source.
const MAX_INBOUND_PER_IP: usize = 16;
/// Time allowed to open a TCP connection to one address of a peer.
const CONNECT_TIMEOUT: Duration = Duration::from_secs(5);
/// A connection that lasted this long resets the dialer's backoff; shorter ones (a peer
/// that disconnects us at once) count as failed attempts.
const STABLE_CONNECTION: Duration = Duration::from_secs(60);
/// Redial interval for a peer on another chain, genesis or protocol version.
const INCOMPATIBLE_BACKOFF_SECS: u64 = 600;
/// Delay before asking a peer again for blocks this node refused as busy.
const BUSY_RETRY: Duration = Duration::from_secs(2);
/// Accepted blocks more than this far below the tip are not relayed: peers that
/// need them fetch them with `SyncRequest`.
const RELAY_DEPTH: u64 = 2 * SYNC_LOOKBACK;

/// A static peer: a socket address, or a `host:port` name resolved again before every
/// connection attempt (bootnodes are named, and their addresses may change).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum PeerAddr {
    /// `IP:port`.
    Socket(SocketAddr),
    /// `host:port`.
    Host(String),
}

impl std::str::FromStr for PeerAddr {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        if let Ok(addr) = s.parse::<SocketAddr>() {
            return Ok(Self::Socket(addr));
        }
        let (host, port) = s
            .rsplit_once(':')
            .ok_or_else(|| format!("peer {s:?} is not IP:port or host:port"))?;
        port.parse::<u16>()
            .map_err(|_| format!("peer {s:?} has an invalid port"))?;
        let valid = |c: char| c.is_ascii_alphanumeric() || c == '-' || c == '.';
        if host.is_empty() || !host.chars().all(valid) {
            return Err(format!("peer {s:?} has an invalid host name"));
        }
        Ok(Self::Host(s.to_owned()))
    }
}

impl std::fmt::Display for PeerAddr {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Socket(addr) => write!(f, "{addr}"),
            Self::Host(host) => f.write_str(host),
        }
    }
}

impl From<SocketAddr> for PeerAddr {
    fn from(addr: SocketAddr) -> Self {
        Self::Socket(addr)
    }
}

/// How one dial attempt ended.
enum Dial {
    /// A connection lasted at least `STABLE_CONNECTION`.
    Stable,
    /// Already connected to it, or networking is paused: nothing was attempted.
    Skipped,
    /// The peer is on another chain, genesis or protocol version.
    Incompatible,
    /// Every address of the peer is this node.
    Myself,
    /// Unresolvable, unreachable, banned, refused, or a short-lived connection.
    Failed,
}

/// How a connection ended.
enum ConnEnd {
    /// No usable handshake: closed, timed out, banned, or a duplicate connection.
    Refused,
    /// The peer is on another chain, genesis or protocol version.
    Incompatible,
    /// The peer is this node: it sent our own nonce.
    Myself,
    /// The peer was registered; the connection lasted this long.
    Ended(Duration),
}

struct PeerHandle {
    addr: SocketAddr,
    outbound: bool,
    tx: mpsc::Sender<WireMessage>,
    best_height: u64,
    invalid_jobs: u32,
    useless_shares: u32,
    useless_window: Instant,
}

#[derive(Default)]
struct SyncState {
    from: u64,
    lookback: u64,
    /// A `SyncRequest` is outstanding.
    outstanding: bool,
    deadline: Option<TokioInstant>,
    /// Last block of the previous batch: the next request waits until it is applied.
    awaiting: Option<(Digest, u64)>,
    /// Ask again from about this height once the instant has passed: the node refused
    /// some of the peer's blocks as busy.
    retry: Option<(TokioInstant, u64)>,
}

struct LruSeen<T> {
    order: VecDeque<T>,
    set: HashSet<T>,
    capacity: usize,
}

impl<T: Copy + Eq + std::hash::Hash> LruSeen<T> {
    fn new(capacity: usize) -> Self {
        Self {
            order: VecDeque::with_capacity(capacity),
            set: HashSet::with_capacity(capacity),
            capacity,
        }
    }

    /// Whether `item` was seen.
    fn contains(&self, item: &T) -> bool {
        self.set.contains(item)
    }

    /// Records `item`; returns false if it was already seen.
    fn mark_seen(&mut self, item: T) -> bool {
        if !self.set.insert(item) {
            return false;
        }
        if self.order.len() >= self.capacity
            && let Some(old) = self.order.pop_front()
        {
            self.set.remove(&old);
        }
        self.order.push_back(item);
        true
    }
}

struct NetShared {
    peers: HashMap<PeerId, PeerHandle>,
    bans: HashMap<Source, Instant>,
    /// Relay ids (`chain::block_relay_id`), not block ids: a copy with a forged
    /// signature or body has the honest `block_id` and must not shadow the genuine block.
    /// Only settled blocks (accepted or invalid) are recorded: copies of a pending block
    /// still reach the chain actor, which remembers who else delivered it.
    seen_blocks: LruSeen<Digest>,
    /// Relay ids (`chain::job_relay_id`), not tx ids, for the same reason.
    seen_jobs: LruSeen<Digest>,
    /// Relay ids (`chain::share_relay_id`), not work ids, for the same reason. Settled
    /// shares only, as for blocks.
    seen_shares: LruSeen<Digest>,
    /// Open inbound connections per remote source (loopback not counted).
    inbound_per_ip: HashMap<Source, usize>,
    paused: bool,
}

/// Why a connection loop ended.
enum Disconnect {
    Closed,
    Ban(Duration, String),
}

/// Manages TCP peers, gossip relay, sync and misbehaviour bans (§4, §8.6).
pub struct PeerManager {
    local_addr: SocketAddr,
    chain_id: u64,
    /// Random per process: a `Handshake` carrying it comes from this node.
    node_nonce: u64,
    next_peer_id: AtomicU64,
    shared: Mutex<NetShared>,
    chain_tx: mpsc::Sender<ChainCmd>,
    mempool_tx: mpsc::Sender<MempoolCmd>,
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    shutdown_rx: watch::Receiver<bool>,
}

/// One inbound connection counted against its source's limit; released on drop.
struct InboundSlot {
    mgr: Arc<PeerManager>,
    source: Source,
}

impl InboundSlot {
    /// Counts a new inbound connection from `addr`, or `None` if its source is at its
    /// limit. Loopback connections are not limited (they carry a dummy slot).
    fn reserve(mgr: &Arc<PeerManager>, addr: SocketAddr) -> Option<Self> {
        let source = Source::of(addr);
        if let Source::Ip(_) = source {
            let mut guard = mgr.lock();
            let count = guard.inbound_per_ip.entry(source).or_insert(0);
            if *count >= MAX_INBOUND_PER_IP {
                return None;
            }
            *count += 1;
        }
        Some(Self {
            mgr: mgr.clone(),
            source,
        })
    }
}

impl Drop for InboundSlot {
    fn drop(&mut self) {
        if let Source::Addr(_) = self.source {
            return;
        }
        let mut guard = self.mgr.lock();
        if let Some(count) = guard.inbound_per_ip.get_mut(&self.source) {
            *count -= 1;
            if *count == 0 {
                guard.inbound_per_ip.remove(&self.source);
            }
        }
    }
}

/// The `version` of a frame that starts like a `Handshake` of any protocol version: the
/// variant tag 0, then the version, both little-endian `u32`.
fn handshake_version(frame: &[u8]) -> Option<u32> {
    let word = |i: usize| -> Option<u32> {
        Some(u32::from_le_bytes(frame.get(i..i + 4)?.try_into().ok()?))
    };
    (word(0)? == 0).then_some(word(4)?)
}

fn is_shutdown(rx: &watch::Receiver<bool>) -> bool {
    *rx.borrow()
}

async fn wait_shutdown(rx: &mut watch::Receiver<bool>) {
    while !*rx.borrow() {
        if rx.changed().await.is_err() {
            return;
        }
    }
}

impl PeerManager {
    /// Binds the listener and starts the accept loop, the dialers and the relay loop.
    #[allow(clippy::too_many_arguments)]
    pub async fn start(
        listen_addr: SocketAddr,
        static_peers: Vec<PeerAddr>,
        chain_id: u64,
        chain_tx: mpsc::Sender<ChainCmd>,
        mempool_tx: mpsc::Sender<MempoolCmd>,
        mut chain_events: broadcast::Receiver<ChainEvent>,
        mut mempool_events: broadcast::Receiver<MempoolEvent>,
        status_rx: watch::Receiver<Arc<StatusSnapshot>>,
        shutdown_rx: watch::Receiver<bool>,
    ) -> std::io::Result<Arc<Self>> {
        let listener = TcpListener::bind(listen_addr).await?;
        let local_addr = listener.local_addr()?;
        let node_nonce = {
            use std::hash::{BuildHasher, Hasher};
            // RandomState is seeded from the operating system's RNG.
            let mut h = std::collections::hash_map::RandomState::new().build_hasher();
            h.write_u128(
                SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_nanos(),
            );
            h.finish()
        };
        let manager = Arc::new(Self {
            local_addr,
            chain_id,
            node_nonce,
            next_peer_id: AtomicU64::new(1),
            shared: Mutex::new(NetShared {
                peers: HashMap::new(),
                bans: HashMap::new(),
                seen_blocks: LruSeen::new(8_192),
                seen_jobs: LruSeen::new(16_384),
                seen_shares: LruSeen::new(16_384),
                inbound_per_ip: HashMap::new(),
                paused: false,
            }),
            chain_tx,
            mempool_tx,
            status_rx,
            shutdown_rx: shutdown_rx.clone(),
        });

        // Accept loop
        let mgr = manager.clone();
        let mut sd = shutdown_rx.clone();
        tokio::spawn(async move {
            loop {
                tokio::select! {
                    () = wait_shutdown(&mut sd) => break,
                    accepted = listener.accept() => {
                        let Ok((stream, addr)) = accepted else { continue };
                        if mgr.is_banned_or_paused(addr) {
                            continue;
                        }
                        let Some(slot) = InboundSlot::reserve(&mgr, addr) else {
                            debug!(%addr, "Too many inbound connections from this IP");
                            continue;
                        };
                        let conn = mgr.clone();
                        tokio::spawn(async move {
                            conn.run_connection(stream, addr, false).await;
                            drop(slot);
                        });
                    }
                }
            }
        });

        // Outbound dialers with exponential backoff (§4.5)
        for peer_addr in static_peers {
            manager.spawn_dialer(peer_addr);
        }

        // Relay loop (§4.6, §8.6)
        let mgr = manager.clone();
        let mut sd = shutdown_rx;
        tokio::spawn(async move {
            loop {
                tokio::select! {
                    () = wait_shutdown(&mut sd) => break,
                    ev = chain_events.recv() => match ev {
                        Ok(ev) => mgr.handle_chain_event(ev),
                        Err(broadcast::error::RecvError::Lagged(n)) => {
                            warn!(skipped = n, "Relay loop lagged behind chain events");
                        }
                        Err(broadcast::error::RecvError::Closed) => break,
                    },
                    ev = mempool_events.recv() => match ev {
                        Ok(ev) => mgr.handle_mempool_event(ev),
                        Err(broadcast::error::RecvError::Lagged(n)) => {
                            warn!(skipped = n, "Relay loop lagged behind mempool events");
                        }
                        Err(broadcast::error::RecvError::Closed) => break,
                    },
                }
            }
        });

        Ok(manager)
    }

    /// Bound listen address.
    pub fn local_addr(&self) -> SocketAddr {
        self.local_addr
    }

    /// Number of connected peers.
    pub fn peer_count(&self) -> usize {
        self.lock().peers.len()
    }

    /// The highest tip height a connected peer has reported, if any peer is connected.
    pub fn best_peer_height(&self) -> Option<u64> {
        self.lock().peers.values().map(|p| p.best_height).max()
    }

    /// Adds an outbound peer with its own reconnecting dialer.
    pub fn add_outbound_peer(self: &Arc<Self>, addr: impl Into<PeerAddr>) {
        self.spawn_dialer(addr.into());
    }

    /// Pauses (drops every connection, refuses new ones) or resumes networking.
    /// Used to partition nodes in tests.
    pub fn set_network_paused(&self, paused: bool) {
        let mut guard = self.lock();
        guard.paused = paused;
        if paused {
            guard.peers.clear();
        }
    }

    fn lock(&self) -> MutexGuard<'_, NetShared> {
        self.shared.lock().unwrap_or_else(|e| e.into_inner())
    }

    fn spawn_dialer(self: &Arc<Self>, peer: PeerAddr) {
        let mgr = self.clone();
        let mut sd = self.shutdown_rx.clone();
        tokio::spawn(async move {
            let mut backoff_secs = 1u64;
            let mut warned = false;
            while !is_shutdown(&sd) {
                // Back off unless the peer kept us: one that refuses the connection (e.g.
                // at its per-IP limit) or drops it at once gets no 1 Hz redial.
                match mgr.dial(&peer, &mut warned).await {
                    Dial::Stable => backoff_secs = 1,
                    Dial::Skipped => {}
                    Dial::Incompatible => {
                        warn!(%peer, "Peer is on another chain or protocol version; retrying rarely");
                        backoff_secs = INCOMPATIBLE_BACKOFF_SECS;
                    }
                    Dial::Myself => {
                        info!(%peer, "Not dialing this peer: it is this node");
                        return;
                    }
                    Dial::Failed => backoff_secs = (backoff_secs * 2).clamp(1, 30),
                }
                tokio::select! {
                    () = tokio::time::sleep(Duration::from_secs(backoff_secs)) => {}
                    () = wait_shutdown(&mut sd) => break,
                }
            }
        });
    }

    /// One attempt to reach `peer`: resolves it, then tries its addresses in turn and
    /// runs the first connection that is established to its end.
    async fn dial(&self, peer: &PeerAddr, warned: &mut bool) -> Dial {
        let addrs: Vec<SocketAddr> = match peer {
            PeerAddr::Socket(addr) => vec![*addr],
            PeerAddr::Host(host) => match tokio::net::lookup_host(host.as_str()).await {
                Ok(addrs) => addrs.collect(),
                Err(e) => {
                    if !std::mem::replace(warned, true) {
                        warn!(%peer, error = %e, "Cannot resolve peer; retrying with backoff");
                    }
                    return Dial::Failed;
                }
            },
        };
        let (mut myself, mut skipped) = (0, false);
        for &addr in &addrs {
            if addr == self.local_addr {
                myself += 1;
                continue;
            }
            if self.has_peer_addr(addr) || self.lock().paused {
                skipped = true;
                continue;
            }
            if self.is_banned(addr) {
                continue;
            }
            let Ok(Ok(stream)) =
                tokio::time::timeout(CONNECT_TIMEOUT, TcpStream::connect(addr)).await
            else {
                continue;
            };
            // Our own address and listen port: a bootnode listed among its own peers.
            if let (Ok(local), Ok(remote)) = (stream.local_addr(), stream.peer_addr())
                && remote == SocketAddr::new(local.ip(), self.local_addr.port())
            {
                myself += 1;
                continue;
            }
            *warned = false;
            match self.run_connection(stream, addr, true).await {
                ConnEnd::Myself => myself += 1,
                ConnEnd::Incompatible => return Dial::Incompatible,
                ConnEnd::Ended(lasted) if lasted >= STABLE_CONNECTION => return Dial::Stable,
                ConnEnd::Ended(_) | ConnEnd::Refused => return Dial::Failed,
            }
        }
        if myself > 0 && myself == addrs.len() {
            Dial::Myself
        } else if skipped {
            Dial::Skipped
        } else {
            Dial::Failed
        }
    }

    fn is_banned(&self, addr: SocketAddr) -> bool {
        let mut guard = self.lock();
        let now = Instant::now();
        guard.bans.retain(|_, until| now < *until);
        guard.bans.contains_key(&Source::of(addr))
    }

    fn is_banned_or_paused(&self, addr: SocketAddr) -> bool {
        self.lock().paused || self.is_banned(addr)
    }

    /// Bans a source and drops every connection from it (their loops notice within one
    /// poll tick), and everything it sent that still awaits verification
    /// (`ChainCmd::CancelSource`; the chain actor has usually done so already).
    fn ban(&self, source: Source, duration: Duration, reason: &str) {
        warn!(?source, secs = duration.as_secs(), reason, "Banning peer");
        {
            let mut guard = self.lock();
            // A shorter ban (e.g. for a stray frame) never shortens a running one.
            let until = Instant::now() + duration;
            let entry = guard.bans.entry(source).or_insert(until);
            *entry = (*entry).max(until);
            guard.peers.retain(|_, p| Source::of(p.addr) != source);
        }
        let chain_tx = self.chain_tx.clone();
        tokio::spawn(async move {
            let _ = chain_tx
                .send(ChainCmd::CancelSource {
                    source,
                    ban: duration,
                })
                .await;
        });
    }

    fn has_peer_addr(&self, addr: SocketAddr) -> bool {
        self.lock().peers.values().any(|p| p.addr == addr)
    }

    fn peer_best_height(&self, peer_id: PeerId) -> u64 {
        self.lock().peers.get(&peer_id).map_or(0, |p| p.best_height)
    }

    /// Lowers the best height a peer claimed to `height` (`--mine-when-synced` waits for
    /// this node to reach the best claimed height).
    fn lower_best_height(&self, peer_id: PeerId, height: u64) {
        if let Some(p) = self.lock().peers.get_mut(&peer_id) {
            p.best_height = p.best_height.min(height);
        }
    }

    fn broadcast(&self, msg: &WireMessage, exclude: Option<PeerId>) {
        let guard = self.lock();
        for (&pid, handle) in &guard.peers {
            if Some(pid) != exclude {
                // A full queue drops gossip frames for that peer (§4.5).
                if handle.tx.try_send(msg.clone()).is_err() {
                    debug!(peer = pid, "Peer queue full; dropping gossip frame");
                }
            }
        }
    }

    fn handle_chain_event(&self, ev: ChainEvent) {
        match ev {
            ChainEvent::BlockAccepted { block, origin } => {
                let exclude = match origin {
                    Origin::Peer(pid, _) => Some(pid),
                    _ => None,
                };
                let tip_height = self.status_rx.borrow().tip.height;
                let height = block.header.context.height;
                if let Ok(relay_id) = chain::block_relay_id(&block) {
                    self.lock().seen_blocks.mark_seen(relay_id);
                }
                if height + RELAY_DEPTH >= tip_height {
                    let msg = WireMessage::GossipBlock(Box::new((*block).clone()));
                    self.broadcast(&msg, exclude);
                }
            }
            ChainEvent::BlockRejected {
                block_id,
                origin: Origin::Peer(pid, source),
                reason,
            } => {
                warn!(peer = pid, id = ?block_id, %reason, "Peer sent an invalid block");
                self.ban(source, INVALID_BAN, &reason);
            }
            // Own shares go to every peer; verified gossip to every peer but its sender.
            ChainEvent::ShareAccepted { share, origin } => {
                let exclude = match origin {
                    Origin::Peer(pid, _) => Some(pid),
                    _ => None,
                };
                if let Ok(relay_id) = chain::share_relay_id(&share) {
                    self.lock().seen_shares.mark_seen(relay_id);
                }
                self.broadcast(
                    &WireMessage::GossipShare(Box::new((*share).clone())),
                    exclude,
                );
            }
            ChainEvent::ShareRejected {
                origin: Origin::Peer(pid, source),
                reason,
            } => {
                warn!(peer = pid, %reason, "Peer sent an invalid share");
                self.ban(source, INVALID_BAN, &reason);
            }
            _ => {}
        }
    }

    fn handle_mempool_event(&self, ev: MempoolEvent) {
        let MempoolEvent::Accepted { tx, origin } = ev;
        let exclude = match origin {
            Origin::Peer(pid, _) => Some(pid),
            _ => None,
        };
        if let Ok(relay_id) = chain::job_relay_id(&tx) {
            self.lock().seen_jobs.mark_seen(relay_id);
        }
        self.broadcast(&WireMessage::GossipJob(tx), exclude);
    }

    /// Runs one connection to its end.
    async fn run_connection(&self, stream: TcpStream, addr: SocketAddr, outbound: bool) -> ConnEnd {
        let source = Source::of(addr);
        let _ = stream.set_nodelay(true);
        let codec = LengthDelimitedCodec::builder()
            .length_field_type::<u32>()
            .big_endian()
            .max_frame_length(MAX_FRAME_BYTES)
            .new_codec();
        let mut framed = Framed::new(stream, codec);

        // Send our Handshake immediately (§4.5 step 2).
        let our_hs = {
            let snap = self.status_rx.borrow();
            WireMessage::Handshake {
                version: WIRE_VERSION,
                chain_id: self.chain_id,
                genesis_id: snap.genesis_id,
                node_nonce: self.node_nonce,
                best_height: snap.tip.height,
                best_block_id: snap.tip.id,
            }
        };
        let Ok(hs_bytes) = codec::encode(&our_hs) else {
            return ConnEnd::Refused;
        };
        if framed.send(Bytes::from(hs_bytes)).await.is_err() {
            return ConnEnd::Refused;
        }

        // Wait at most HANDSHAKE_TIMEOUT for the peer's Handshake (§4.5 step 3).
        // A timeout or closed socket is not misbehaviour; a wrong first frame is.
        let (peer_best_height, peer_best_id) = match tokio::time::timeout(
            HANDSHAKE_TIMEOUT,
            framed.next(),
        )
        .await
        {
            Ok(Some(Ok(bytes))) => match codec::decode::<WireMessage>(&bytes) {
                Ok(WireMessage::Handshake {
                    version,
                    chain_id,
                    genesis_id,
                    node_nonce,
                    best_height,
                    best_block_id,
                }) => {
                    if node_nonce == self.node_nonce {
                        debug!(%addr, "Connected to this node itself");
                        return ConnEnd::Myself;
                    }
                    let ours = self.status_rx.borrow().genesis_id;
                    if version != WIRE_VERSION || chain_id != self.chain_id || genesis_id != ours {
                        info!(%addr, version, chain_id, %genesis_id, "Peer is on another chain, genesis or protocol version");
                        return ConnEnd::Incompatible;
                    }
                    (best_height, best_block_id)
                }
                // A Handshake of another protocol version need not decode (its fields
                // differ): it is recognised by its variant tag and version.
                _ if handshake_version(&bytes).is_some_and(|v| v != WIRE_VERSION) => {
                    info!(%addr, version = ?handshake_version(&bytes), "Peer speaks another protocol version");
                    return ConnEnd::Incompatible;
                }
                _ => {
                    self.ban(source, PROTOCOL_BAN, "first frame is not a valid Handshake");
                    return ConnEnd::Refused;
                }
            },
            Ok(Some(Err(e))) if e.kind() == std::io::ErrorKind::InvalidData => {
                self.ban(source, PROTOCOL_BAN, "oversize frame");
                return ConnEnd::Refused;
            }
            _ => {
                debug!(%addr, "No handshake from peer");
                return ConnEnd::Refused;
            }
        };

        // Register the peer, deduplicating outbound connections by address (§4.5 step 4).
        let peer_id = self.next_peer_id.fetch_add(1, Ordering::Relaxed);
        let (write_tx, mut write_rx) = mpsc::channel::<WireMessage>(256);
        {
            let mut guard = self.lock();
            if guard.paused
                || (outbound && guard.peers.values().any(|p| p.outbound && p.addr == addr))
            {
                return ConnEnd::Refused;
            }
            guard.peers.insert(
                peer_id,
                PeerHandle {
                    addr,
                    outbound,
                    tx: write_tx.clone(),
                    best_height: peer_best_height,
                    invalid_jobs: 0,
                    useless_shares: 0,
                    useless_window: Instant::now(),
                },
            );
        }
        info!(peer = peer_id, %addr, outbound, peer_best_height, "Connected peer");
        let connected_at = Instant::now();

        let (mut sink, mut frames) = framed.split();
        let write_task = tokio::spawn(async move {
            while let Some(msg) = write_rx.recv().await {
                let Ok(bytes) = codec::encode(&msg) else {
                    break;
                };
                if sink.send(Bytes::from(bytes)).await.is_err() {
                    break;
                }
            }
        });

        let mut sync = SyncState::default();
        if peer_best_height > 0 && !self.has_block(peer_best_id).await {
            self.start_sync(&write_tx, &mut sync, peer_best_height);
        }

        let mut poll = tokio::time::interval(Duration::from_millis(100));
        let mut shutdown = self.shutdown_rx.clone();
        let mut req_window = Instant::now();
        let mut req_count = 0u32;
        let reason = loop {
            let deadline = sync.deadline;
            tokio::select! {
                () = wait_shutdown(&mut shutdown) => break Disconnect::Closed,
                frame = frames.next() => {
                    // Banned meanwhile (its source sent something invalid): read no more.
                    if !self.lock().peers.contains_key(&peer_id) {
                        break Disconnect::Closed;
                    }
                    let bytes = match frame {
                        None => break Disconnect::Closed,
                        Some(Err(e)) if e.kind() == std::io::ErrorKind::InvalidData => {
                            break Disconnect::Ban(PROTOCOL_BAN, "oversize frame".into());
                        }
                        // Resets and other I/O errors are not misbehaviour.
                        Some(Err(_)) => break Disconnect::Closed,
                        Some(Ok(bytes)) => bytes,
                    };
                    let Ok(msg) = codec::decode::<WireMessage>(&bytes) else {
                        break Disconnect::Ban(PROTOCOL_BAN, "undecodable frame".into());
                    };
                    if req_window.elapsed() >= Duration::from_secs(1) {
                        req_window = Instant::now();
                        req_count = 0;
                    }
                    if matches!(msg, WireMessage::SyncRequest { .. }) {
                        req_count += 1;
                        if req_count > 10 {
                            continue; // rate limit (§4.8): drop the excess requests
                        }
                    }
                    if let Err(d) = self.handle_peer_message(peer_id, source, msg, &write_tx, &mut sync).await {
                        break d;
                    }
                }
                () = async {
                    match deadline {
                        Some(d) => tokio::time::sleep_until(d).await,
                        None => std::future::pending().await,
                    }
                } => {
                    debug!(peer = peer_id, "Sync request timed out");
                    // A peer that does not answer is not ahead of us, whatever it claimed.
                    // (Waiting for our own verification of its last batch is not its fault.)
                    if sync.outstanding {
                        let tip = self.status_rx.borrow().tip.height;
                        self.lower_best_height(peer_id, tip);
                    }
                    sync = SyncState::default();
                }
                _ = poll.tick() => {
                    // Paused, or banned meanwhile: a block or share rejected after its
                    // asynchronous check removes the peer (ChainEvent::*Rejected).
                    {
                        let guard = self.lock();
                        if guard.paused || !guard.peers.contains_key(&peer_id) {
                            break Disconnect::Closed;
                        }
                    }
                    if let Some((await_id, last_h)) = sync.awaiting
                        && self.has_block(await_id).await
                    {
                        sync.awaiting = None;
                        sync.from = last_h + 1;
                        self.send_sync_request(&write_tx, &mut sync);
                    }
                    if let Some((at, hint)) = sync.retry
                        && TokioInstant::now() >= at
                        && !sync.outstanding
                    {
                        sync.retry = None;
                        self.start_sync(&write_tx, &mut sync, hint);
                    }
                }
            }
        };

        write_task.abort();
        self.lock().peers.remove(&peer_id);
        match reason {
            Disconnect::Closed => debug!(peer = peer_id, %addr, "Disconnected peer"),
            Disconnect::Ban(duration, why) => self.ban(source, duration, &why),
        }
        ConnEnd::Ended(connected_at.elapsed())
    }

    async fn handle_peer_message(
        &self,
        peer_id: PeerId,
        source: Source,
        msg: WireMessage,
        write_tx: &mpsc::Sender<WireMessage>,
        sync: &mut SyncState,
    ) -> Result<(), Disconnect> {
        let origin = Origin::Peer(peer_id, source);
        match msg {
            WireMessage::Handshake { .. } => {
                Err(Disconnect::Ban(PROTOCOL_BAN, "second Handshake".into()))
            }
            WireMessage::GossipBlock(block) => {
                let height = block.header.context.height;
                let Ok(relay_id) = chain::block_relay_id(&block) else {
                    return Ok(());
                };
                if self.lock().seen_blocks.contains(&relay_id) {
                    return Ok(());
                }
                let ack = self.import_block(Arc::new(*block), origin).await;
                // A gossiped block raises the height the peer claims to at most one past
                // our tip: the height of an orphan (even one queued behind a pending
                // parent) is unchecked, and such a header costs nothing to make.
                if matches!(
                    ack,
                    ImportAck::Queued | ImportAck::Duplicate | ImportAck::Deferred
                ) {
                    let next = self.status_rx.borrow().tip.height + 1;
                    if let Some(p) = self.lock().peers.get_mut(&peer_id) {
                        p.best_height = p.best_height.max(height.min(next));
                    }
                }
                match ack {
                    ImportAck::Orphan if height == 1 => {
                        warn!(peer = peer_id, "genesis mismatch at height 1");
                        Err(Disconnect::Closed)
                    }
                    ImportAck::Orphan => {
                        if !sync.outstanding && sync.awaiting.is_none() {
                            self.start_sync(write_tx, sync, height);
                        }
                        Ok(())
                    }
                    ImportAck::Invalid(reason) => {
                        self.lock().seen_blocks.mark_seen(relay_id);
                        Err(Disconnect::Ban(INVALID_BAN, reason))
                    }
                    // Nobody relays a block twice: fetch it from this peer in a moment.
                    ImportAck::Busy => {
                        if !sync.outstanding && sync.awaiting.is_none() && sync.retry.is_none() {
                            sync.retry = Some((TokioInstant::now() + BUSY_RETRY, height));
                        }
                        Ok(())
                    }
                    _ => Ok(()),
                }
            }
            WireMessage::GossipJob(tx) => {
                let Ok(relay_id) = chain::job_relay_id(&tx) else {
                    return Ok(());
                };
                if !self.lock().seen_jobs.mark_seen(relay_id) {
                    return Ok(());
                }
                let (reply_tx, reply_rx) = oneshot::channel();
                let cmd = MempoolCmd::Insert {
                    tx,
                    origin,
                    reply: reply_tx,
                };
                if self.mempool_tx.send(cmd).await.is_err() {
                    return Ok(());
                }
                if let Ok(Err(MempoolReject::Invalid { message, .. })) = reply_rx.await {
                    let mut guard = self.lock();
                    if let Some(p) = guard.peers.get_mut(&peer_id) {
                        p.invalid_jobs += 1;
                        if p.invalid_jobs >= MAX_INVALID_JOBS {
                            return Err(Disconnect::Ban(INVALID_BAN, message));
                        }
                    }
                }
                Ok(())
            }
            WireMessage::GossipShare(share) => {
                // Ignored and duplicate shares cost us checks but are free to make (no
                // signature or work is needed before they are dropped): budget them.
                // Past the budget the peer is throttled, not banned: an honest peer
                // that is syncing, or relaying to us while we catch up, sends many.
                if self.useless_share_budget_spent(peer_id) {
                    return Ok(());
                }
                let Ok(relay_id) = chain::share_relay_id(&share) else {
                    return Ok(());
                };
                if self.lock().seen_shares.contains(&relay_id) {
                    return Ok(());
                }
                let ack = self.import_share(share, origin).await;
                // Only settled outcomes are remembered: an ignored share (e.g. its parent
                // had not arrived yet) may be useful when relayed again later, and copies
                // of a pending one must still reach the chain actor in case its check is
                // cancelled. Accepted shares are recorded on ChainEvent::ShareAccepted.
                if matches!(ack, ShareAck::Duplicate | ShareAck::Invalid(_)) {
                    self.lock().seen_shares.mark_seen(relay_id);
                }
                if matches!(ack, ShareAck::Ignored(_) | ShareAck::Duplicate)
                    && let Some(p) = self.lock().peers.get_mut(&peer_id)
                {
                    p.useless_shares = p.useless_shares.saturating_add(1);
                }
                // Invalid shares get the peer banned here or, when the work check fails
                // later, through ChainEvent::ShareRejected.
                match ack {
                    ShareAck::Invalid(reason) => Err(Disconnect::Ban(INVALID_BAN, reason)),
                    _ => Ok(()),
                }
            }
            WireMessage::SyncRequest { from_height } => {
                let (reply_tx, reply_rx) = oneshot::channel();
                let cmd = ChainCmd::GetCanonicalRange {
                    from_height,
                    reply: reply_tx,
                };
                let blocks = if self.chain_tx.send(cmd).await.is_ok() {
                    reply_rx.await.unwrap_or_default()
                } else {
                    Vec::new()
                };
                let blocks = blocks.into_iter().map(|b| (*b).clone()).collect();
                // SyncResponse frames are never dropped (§4.5).
                let _ = write_tx.send(WireMessage::SyncResponse { blocks }).await;
                Ok(())
            }
            WireMessage::SyncResponse { blocks } => {
                self.handle_sync_response(origin, blocks, write_tx, sync)
                    .await
            }
        }
    }

    async fn handle_sync_response(
        &self,
        origin: Origin,
        blocks: Vec<Block>,
        write_tx: &mpsc::Sender<WireMessage>,
        sync: &mut SyncState,
    ) -> Result<(), Disconnect> {
        let Origin::Peer(peer_id, _) = origin else {
            return Ok(());
        };
        if !sync.outstanding {
            // Late answer to a request that already timed out: ignore it.
            debug!(peer = peer_id, "Ignoring unexpected SyncResponse");
            return Ok(());
        }
        sync.outstanding = false;
        sync.deadline = None;
        let (Some(first), Some(last)) = (blocks.first(), blocks.last()) else {
            // It has nothing from `from` on, whatever height it claimed.
            self.lower_best_height(peer_id, sync.from.saturating_sub(1));
            return Ok(());
        };
        let (first_height, last_id, last_height) = (
            first.header.context.height,
            last.header.block_id,
            last.header.context.height,
        );
        // An honest answer starts at the requested height; anything else shows nothing
        // about the height the peer claimed.
        if first_height != sync.from {
            self.lower_best_height(peer_id, sync.from.saturating_sub(1));
            return Ok(());
        }
        let encoded_len = codec::encode(&blocks).map_or(0, |b| b.len());
        let full = blocks.len() == MAX_SYNC_BLOCKS || encoded_len >= MAX_SYNC_BYTES;

        let mut first_ack = None;
        let mut nothing_new = true;
        for blk in blocks {
            let height = blk.header.context.height;
            let ack = self.import_block(Arc::new(blk), origin).await;
            match ack {
                ImportAck::Invalid(reason) => return Err(Disconnect::Ban(INVALID_BAN, reason)),
                // The rest would only be parked behind a block that is not pending: ask
                // again from here in a moment.
                ImportAck::Busy => {
                    sync.awaiting = None;
                    sync.retry = Some((TokioInstant::now() + BUSY_RETRY, height));
                    return Ok(());
                }
                _ => {}
            }
            nothing_new &= ack == ImportAck::Duplicate;
            first_ack.get_or_insert(ack);
        }
        // A short batch of blocks we already have: the peer has nothing beyond it.
        if nothing_new && !full {
            self.lower_best_height(peer_id, last_height);
        }

        if first_ack == Some(ImportAck::Orphan) {
            // Parent unknown and not pending: the fork point is lower (§4.7).
            if first_height == 1 {
                warn!(peer = peer_id, "genesis mismatch at height 1");
                return Err(Disconnect::Closed);
            }
            sync.lookback = sync.lookback.saturating_mul(2);
            if sync.lookback > MAX_REORG_DEPTH {
                warn!(peer = peer_id, "no common ancestor within reorg depth");
                return Err(Disconnect::Closed);
            }
            sync.from = sync.from.saturating_sub(sync.lookback).max(1);
            self.send_sync_request(write_tx, sync);
            return Ok(());
        }

        if full || self.peer_best_height(peer_id) > last_height {
            if self.has_block(last_id).await {
                sync.from = last_height + 1;
                self.send_sync_request(write_tx, sync);
            } else {
                // Verification is sequential: wait for the batch to be applied (§4.7).
                sync.awaiting = Some((last_id, last_height));
                sync.deadline = Some(TokioInstant::now() + SYNC_TIMEOUT);
            }
        }
        Ok(())
    }

    fn start_sync(
        &self,
        write_tx: &mpsc::Sender<WireMessage>,
        sync: &mut SyncState,
        hint_height: u64,
    ) {
        let our_best = self.status_rx.borrow().tip.height;
        sync.lookback = SYNC_LOOKBACK;
        sync.awaiting = None;
        sync.from = hint_height
            .min(our_best + 1)
            .saturating_sub(SYNC_LOOKBACK)
            .max(1);
        self.send_sync_request(write_tx, sync);
    }

    fn send_sync_request(&self, write_tx: &mpsc::Sender<WireMessage>, sync: &mut SyncState) {
        sync.outstanding = true;
        sync.deadline = Some(TokioInstant::now() + SYNC_TIMEOUT);
        let _ = write_tx.try_send(WireMessage::SyncRequest {
            from_height: sync.from,
        });
    }

    async fn has_block(&self, id: Digest) -> bool {
        let (tx, rx) = oneshot::channel();
        if self
            .chain_tx
            .send(ChainCmd::HasBlock { id, reply: tx })
            .await
            .is_err()
        {
            return false;
        }
        rx.await.unwrap_or(false)
    }

    /// Whether the peer has sent its quota of useless shares this minute (or is gone).
    fn useless_share_budget_spent(&self, peer_id: PeerId) -> bool {
        let mut guard = self.lock();
        let Some(p) = guard.peers.get_mut(&peer_id) else {
            return true;
        };
        if p.useless_window.elapsed() >= Duration::from_secs(60) {
            p.useless_window = Instant::now();
            p.useless_shares = 0;
        }
        p.useless_shares >= MAX_USELESS_SHARES_PER_MIN
    }

    async fn import_share(&self, share: Box<ShareProof>, origin: Origin) -> ShareAck {
        let (tx, rx) = oneshot::channel();
        let cmd = ChainCmd::ImportShare {
            share,
            origin,
            ack: Some(tx),
        };
        if self.chain_tx.send(cmd).await.is_err() {
            return ShareAck::Duplicate;
        }
        rx.await.unwrap_or(ShareAck::Duplicate)
    }

    async fn import_block(&self, block: Arc<Block>, origin: Origin) -> ImportAck {
        let (tx, rx) = oneshot::channel();
        let cmd = ChainCmd::ImportBlock {
            block,
            origin,
            ack: Some(tx),
        };
        if self.chain_tx.send(cmd).await.is_err() {
            return ImportAck::Duplicate;
        }
        rx.await.unwrap_or(ImportAck::Duplicate)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn handshakes_of_any_version_are_recognised_by_their_prefix() {
        // A v3 Handshake: version, chain_id, best_height, best_block_id (88 bytes).
        let mut v3 = vec![0u8; 4];
        v3.extend_from_slice(&3u32.to_le_bytes());
        v3.extend_from_slice(&0x504C_4154u64.to_le_bytes());
        v3.extend_from_slice(&7u64.to_le_bytes());
        v3.extend_from_slice(&[9; 64]);
        assert!(
            codec::decode::<WireMessage>(&v3).is_err(),
            "v3 does not decode as v4"
        );
        assert_eq!(handshake_version(&v3), Some(3));

        let v4 = codec::encode(&WireMessage::Handshake {
            version: WIRE_VERSION,
            chain_id: 1,
            genesis_id: Digest::ZERO,
            node_nonce: 2,
            best_height: 3,
            best_block_id: Digest::ZERO,
        })
        .unwrap();
        assert_eq!(handshake_version(&v4), Some(WIRE_VERSION));
        let other = codec::encode(&WireMessage::SyncRequest { from_height: 1 }).unwrap();
        assert_eq!(handshake_version(&other), None);
        assert_eq!(handshake_version(&[0, 0, 0]), None);
    }
}
EOF

