// GET /api/status (§9.3)
// ---------------------------------------------------------------------------

#[derive(Serialize)]
struct StatusResponse {
    chain: ChainInfoDto,
    node: NodeInfoDto,
    tip: TipInfoDto,
    mining: MiningInfoDto,
    verification: VerificationInfoDto,
    mempool: MempoolInfoDto,
    ledger: LedgerInfoDto,
    commercial_consensus_weight: u64,
}

#[derive(Serialize)]
struct ChainInfoDto {
    name: String,
    chain_id: String,
    genesis_id: String,
